programs.luna:
"""Estimate a small education/design-related response from the current word.

The clearest large responses occur on words about curriculum, educational
formats, and designed or structured activities; words naming skills tend to
have the opposite sign. Most tokens do not match these concepts and get zero.
"""

READS = ()

DESIGN_AND_CURRICULUM = {
    "designed", "structured", "curriculum", "educational", "content",
    "内容", "形式", "办学", "制度", "模式", "科目", "模拟",
    "atmosphere", "style",
}

SKILL_AND_EXPERTISE = {
    "skills", "skill", "技巧", "技能", "选手", "writing",
}


def step(carry, prefix, upstream):
    word = prefix.token_strings[-1].strip().lower()
    if word in DESIGN_AND_CURRICULUM:
        return None, -0.08
    if word in SKILL_AND_EXPERTISE:
        return None, 0.08
    return None, 0.0

programs.sol:
"""Recognize abbreviated labels, especially three-letter capital initialisms.

The response is negative for letter sequences unlike English syllables, and
for familiar technical abbreviations, units and filename extensions. English
syllables and ordinary words are usually left at zero. Python/TypeScript
filename extensions instead get a small positive response. Two-letter labels are
weaker, and a leading space strengthens them. 'Hmm' is a separate small
negative response. A README's Markdown extension is stronger than other .md
extensions; this is the only dependence on earlier tokens.
"""
READS = ()
VOWELS = set('AEIOUY')
# Consonant pairs that can begin/end ordinary English syllables.
ONSETS = set('CH SH TH PH WH BR CR DR FR GR PR TR WR BL CL FL GL PL SL '
             'SP ST SC SK SW SM SN TW DW QU'.split())
CODAS = set('CH SH TH CK CT FT LD LF LK LL LM LP LT MP ND NG NK NT PT '
            'RB RC RD RF RG RK RL RM RN RP RR RS RT RV '
            'BB CC DD FF GG NN PP TT ZZ LC LS LV MB MS '
            'NC NF NS NV BS BT FS SC SM GN WN SK SP SS ST TS PS'.split())
FUNCTION_WORDS = set('OF IN IS IT AS AT AN OR ON IF AM UP TO DO GO SO NO '
                     'BE BY HE ME WE MY US'.split())
CODE_LABELS = set('STR INT MSG EXP EXT PTR LEN IDX MAX MIN SRC DST '
                  'TMP CMD CTX FMT STD TXT PTS PCT SPC TRL'.split())
ROMAN_NUMERALS = set('II III IV VI VII VIII IX XI XII XIII XIV XV XVI '
                     'XVII XVIII XIX XX'.split())
FAMILIAR_ABBREVIATIONS = set(
    'USA API URL EOF EPS ABC AWS AMD HIV LED GUI IDE ISO ICU SEO SQL PHP XML '
    'PDF DOM RAM'.split())
LONG_ABBREVIATIONS = set('NCAA ESPN UEFA NYPD IPCC OECD USDA UNESCO NOAA USSR '
                       'NASCAR NATO NASA LGBT LGBTQ ISBN ISSN PTSD'.split())
LONG_TECH = set('HTTP HTML JSON YAML GPIO USART UUID IEEE BIOS CUDA ASCII '
                'JPEG TIFF HDMI JDBC LLVM DHCP HMAC POSIX UART SATA'.split())
TECH_ABBREVIATIONS = set('csv rgb rdf ssh ssl tcp udp rpc ipc vpn usb sdk '
                         'gcd dfs bfs rhs lhs css dll grpc tsp ppm rpm'.split())
COMMON_TECH_LABELS = set('xml yaml yml php svg jsx gzip cpp cfg pkg cli '
                           'url'.split())
MIXED_ABBREVIATIONS = set('pH PhD IoT NaN iOS OAuth'.split())
UNITS = set('GHz MHz kHz kWh mAh mmHg'.split())
LIGHT_EXTENSIONS = set('.js .cpp .php .png .jpg .txt .pdf .hpp'.split())
OTHER_EXTENSIONS = set('.yaml .yml .xml .cfg .dll .htm .owl .stderr'.split())


def response(token):
    raw = token.strip()
    word = raw.lstrip('._/-(')
    space = token.startswith((' ', '\t', '\n'))
    if raw in LIGHT_EXTENSIONS:
        return -0.45
    if raw in OTHER_EXTENSIONS:
        return -1.0
    if raw in ('.py', '.ts'):
        return 0.23
    if word == 'npm':
        return -2.0 if space else -2.4
    if word in ('DNA', 'RNA', 'mRNA', 'tRNA', 'rRNA'):
        return -3.2
    if word in ('CEO', 'CFO', 'CTO', 'COO', 'MBA'):
        return -3.2
    if word in LONG_ABBREVIATIONS:
        return -2.9
    if word in LONG_TECH:
        return -1.65
    if word in MIXED_ABBREVIATIONS or word in UNITS:
        return -2.0
    if word in TECH_ABBREVIATIONS:
        return -1.65
    if word in COMMON_TECH_LABELS:
        return -0.85
    if word in ('APIs', 'LEDs', 'URLs', 'DVDs', 'PCs'):
        return -1.9
    if word in ('kB', 'mM', 'Hz'):
        return -0.7
    if raw in ('°C', '°F', '℃'):
        return -0.9
    if word in ('Hmm', 'hmm'):
        return -0.62 if space else -0.75
    if not (word.isascii() and word.isalpha() and word.isupper()):
        return 0.0
    if word in CODE_LABELS:
        return -0.15
    if word in ROMAN_NUMERALS:
        return -0.85 if space else -0.6
    if word in ('CPU', 'GPU', 'USB', 'SDK'):
        return -2.7
    if word in FAMILIAR_ABBREVIATIONS:
        return -1.6 if space else -1.25
    if word == 'README':
        return -1.15
    n = len(word)
    shape = ''.join('V' if c in VOWELS else 'C' for c in word)
    if n == 2:
        if word in FUNCTION_WORDS:
            return -0.8 if word == 'US' and space else 0.0
        if word in ('AI', 'EU', 'UI', 'UK', 'TV'):
            return -1.2 if space else -0.6
        if shape == 'CC':
            if word in ONSETS:
                return -0.3 if space else -0.05
            return -0.7 if space else -0.3
        return -0.35 if space else 0.0
    if n == 3:
        if shape == 'CCC':
            if word in ('CHR', 'SCR', 'SCH', 'SPR', 'SPL', 'THR'):
                return 0.0
            if len(set(word)) == 1:
                return -1.0
            return -2.65 if space else -2.2
        if shape == 'CCV' and word[:2] not in ONSETS:
            return -3.0 if space else -2.5
        if shape == 'VCC' and word[-2:] not in CODAS:
            return -2.7 if space else -2.2
    if n == 4 and shape == 'CCCC':
        return -1.8
    return 0.0


def step(carry, prefix, upstream):
    document = prefix.document_ids[-1]
    token = prefix.token_strings[-1]
    previous = carry[1] if carry and carry[0] == document else ''
    if token.strip() == '.md':
        value = -0.5
        if previous.strip() == 'README':
            value = -1.05 if previous.startswith(' ') else -0.8
    else:
        value = response(token)
    return (document, token), value

"""Approximate a mixture of local wording and typography responses.

Result/inference verbs become more negative in modal clauses, especially
with 'we'. Letter fragments depend on the preceding sign or word stem.
Smaller offsets cover function words, suffix-like fragments, and message
markers. Most other tokens are zero. This is a local pattern approximation,
not a claim that the component performs semantic reasoning.
"""
READS = ()

# Small empirical offsets for function words and connecting adverbs.
WORD_OFFSETS = {
    'other': 0.057, 'any': 0.032, 'several': 0.059,
    'either': -0.070, 'neither': -0.051, 'both': -0.036,
    'also': -0.049, 'instead': -0.102, 'perhaps': 0.053,
    'quite': 0.124, 'almost': -0.107, 'further': -0.071,
    'here': 0.050, 'alone': -0.122, 'out': 0.028,
    'over': 0.030, 'up': 0.022, 'about': -0.027,
    'it': -0.013, 'will': -0.017, 'us': -0.021,
}
VERB_OFFSETS = {
    'get': -0.030, 'gets': -0.145, 'got': -0.075,
    'getting': -0.100, 'expect': -0.110,
    'conclude': -0.160, 'concluded': -0.150,
    'concludes': -0.150, 'concluding': -0.150,
    'selected': -0.090, 'selecting': -0.050, 'selects': -0.040,
}
MARKERS = {
    '<tool_response>': -0.132, '<tool_call>': 0.080,
    '<think>': -0.112, '</think>': -0.044,
    '<|im_end|>': -0.029, '<|endoftext|>': -0.019,
}
FRAGMENTS = {'able': -0.080, 'ed': -0.022, 'ier': 0.065}
SYMBOLS = {';': -0.025, '{': 0.038, ']': 0.025,
           '||': -0.061, '\\n': -0.037}
MODALS = {'can', 'could', 'will', 'would', 'should', 'may', 'might', 'shall'}
GIVING = {'give', 'gives', 'giving', 'given', 'provide', 'provides',
          'provided', 'providing', 'show', 'shows', 'showing'}


def local_value(token, previous='', before_previous=''):
    w, p, b = (s.strip().lower() for s in
               (token, previous, before_previous))
    value = MARKERS.get(token, FRAGMENTS.get(token, SYMBOLS.get(token, 0.0)))
    modal = {'\u2019ll': 'will', "'ll": 'will',
             '\u2019d': 'would', "'d": 'would'}.get(p, p)
    if modal not in MODALS:
        modal = b if p in {'not', 'we', 'you', 'be'} and b in MODALS else ''
    if token.startswith(' '):
        value = WORD_OFFSETS.get(w, VERB_OFFSETS.get(w, 0.0))
        if w in {'get', 'expect', 'conclude', 'concluded', 'see', 'know'}:
            if modal:
                value = -0.30 if modal == 'will' else -0.19
                if w == 'expect':
                    value = -0.38 if modal in {'would', 'should'} else -0.28
                elif w in {'conclude', 'concluded'}:
                    value = -0.30
                elif w in {'see', 'know'}:
                    value = -0.14 if modal == 'will' else -0.08
                if b == 'we' or (p == 'we' and b in MODALS):
                    value -= 0.13 if w != 'expect' else 0.24
            elif p == 'we':
                value = -0.20 if w in {'get', 'conclude'} else -0.07
                if w == 'expect':
                    value = -0.24
            elif w == 'see':
                value = 0.060 if p == 'to' else (
                    -0.10 if p in {'me', 'us', "'s", '’s', 'please'} else 0.01
                )
            elif w == 'know' and p in {"'t", '’t', 'dont'}:
                value = 0.055
            elif w in {'get', 'expect'} and (
                previous.isspace() or p in {'def', 'function', 'int', 'string'}
            ):
                value = -0.01
        if w == 'getting':
            if p in {'is', 'are', 'be'}:
                value = -0.15
            elif p == 'of' and b == 'probability':
                value = -0.42
        if w in {'selected', 'selecting', 'selects'} and p == 'randomly':
            value = -0.52
        if w == 'significant':
            value = 0.09
            if p in {'no', 'not', 'more', 'most', 'very', 'any'}:
                value = 0.20
            elif p == 'highly':
                value = 0.30
            elif p in {'a', 'an'}:
                value = 0.03
        if w == 'will' and p in {'we', 'you', 'they'}:
            value -= 0.06
        elif w == 'us' and p in GIVING | {'tells', 'tell', 'let', 'allow', 'allows'}:
            value -= 0.14
    if token in {'.Printf', '.Sprintf', '.WriteLine'}:
        value = -0.16
    if len(token) == 1 and token.isascii() and token.isalpha():
        value = 0.020 if token in 'enpxX' else 0.007
        lower = token.islower()
        if previous.rstrip().endswith(('-', '−')):
            value = 0.16 if lower else 0.075
            # Common scalar symbols have the strongest minus-sign response.
            if token in 'axe':
                value = 0.24
            if not previous.startswith(' '):
                value -= 0.02
        elif previous.rstrip().endswith('+'):
            value = 0.11 if lower else 0.05
        elif previous.rstrip().endswith('('):
            value = -0.075 if lower else -0.009
            if not previous.startswith(' '):
                value += 0.02
        elif previous.rstrip().endswith('[') or '\n' in previous:
            value = -0.02
        elif p.isdigit():
            value = 0.023
        elif token == 'e' and p.isalpha():
            value = 0.05
            if p in {'low', 'domain', 'town'}:
                value = 0.65 if p != 'town' else 0.53
            elif p in {'row', 'crow'}:
                value = 0.32
            elif p.endswith(('n', 'w')):
                value = 0.08
    if token == '0' and previous.rstrip().endswith(('-', '−')):
        value = 0.14 if previous.startswith(' ') else 0.075
    if token == ' States' and p == 'united':
        value = 0.185
    elif token == '.S' and previous in {' U', 'U'}:
        value = 0.155 if previous.startswith(' ') else 0.09
    elif token == 'p' and p == 'south':
        value = 0.70
    return float(value)


def step(carry, prefix, upstream):
    document = prefix.document_ids[-1]
    previous, before = ('', '') if carry is None or carry[0] != document else carry[1:]
    token = prefix.token_strings[-1]
    return (document, token, previous), local_value(token, previous, before)

programs.luna:
"""Predict the overall mean, nudged down for four modal-backed verbs and up
for single-letter e/p continuations of capitalized fragments."""
READS = ()

NEGATIVE_VERBS = {"expect", "conclude", "concluded", "get"}
MODALS = {"would", "can", "might", "will", "could", "should", "may", "must"}
BACKGROUND = -0.000635
STRENGTH = 0.11


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        previous = ()
    else:
        previous = carry[1:]

    token = prefix.token_strings[-1]
    word = token.strip()
    signal = 0.0

    if word in NEGATIVE_VERBS and token[:1].isspace():
        context = {part.strip().lower() for part in previous}
        if context & MODALS:
            signal = -1.0

    if token in {"e", "p"} and previous:
        last = previous[-1].lstrip()
        starts_name = bool(last) and last[0].isupper()
        if not starts_name and len(previous) > 1:
            earlier = previous[-2].lstrip()
            starts_name = bool(earlier) and earlier[0].isupper() and last.islower()
        if starts_name:
            signal = 1.0

    new_carry = (doc, *(previous + (token,))[-2:])
    return new_carry, BACKGROUND + STRENGTH * signal

"""A lexical sketch of a few high-activation grammatical cues.

It assigns positive guesses to “how” and helping verbs, with stronger guesses
for some auxiliaries that were especially prominent. All other tokens get zero;
this is a sparse proxy, not a parser.
"""
READS = ()

HOW = {"how"}
STRONG_AUX = {"has", "been", "may", "shall"}
COMMON_AUX = {
    "am", "is", "are", "was", "were", "be", "being",
    "have", "had", "do", "does", "did", "can", "must", "will",
    "should",
}
WEAKER_MODALS = {"could", "might", "would"}


def step(carry, prefix, upstream):
    word = prefix.token_strings[-1].strip().lower()
    if word in HOW:
        return None, 0.76
    if word in STRONG_AUX:
        return None, 0.65
    if word in COMMON_AUX:
        return None, 0.40
    if word in WEAKER_MODALS:
        return None, 0.22
    if word.endswith("s"):
        return None, 0.05
    return None, 0.0

programs.haiku:
"""layers.0.mlp.down_proj:453 -- a "for / about / regarding" detector.

What it does: this component fires on the preposition "for" (and "about") when it
introduces a purpose, recipient, or topic, and on the same idea written in other
languages (关于, 对于, 于, について, для, für, ...). It is strongest on words that start
a clause or a code loop ("As for me", "for (int i...", "For example") and near zero
on "for" that a preceding verb or adjective takes ("preparing for", "asked for").
Chat-markup tags get small fixed offsets.

Main program: a lookup of the words, plus one context rule for the English "for".
"""

READS = ()

# English "for", as a word, capitalised, or as a code keyword.
FOR_WORDS = {" for", "for", " For", "For", "FOR", "_FOR", "_for", "\tfor", "-for"}
ABOUT_WORDS = {" about", "about", "/about"}
CAP_ABOUT = {" About", "About", ">About"}

# Translations of "for / about / regarding" (Chinese, Japanese, Korean, other European
# languages), with their typical activation.
TOPIC_WORDS = {
    "关于": 4.0, "關於": 4.0, "对于": 2.8, "對於": 2.8, "至於": 2.3, "于": 1.4, "於": 1.1,
    "就": 0.7, "针对": 0.7, "有关": 0.7, "基于": 0.7, "用于": 0.9,
    " tentang": 1.4, " 대한": 1.1, " für": 0.4, " для": 0.6, " về": 1.6,
    "について": 1.9, "に関して": 1.9, "Regarding": 1.3,
}

# Chat-markup tags: small, fixed offsets.
TAGS = {"</tool_call>": -0.37, "<tool_response>": -0.36, "</think>": 0.38, "<|im_start|>": 0.14}


def step(carry, prefix, upstream):
    tok = prefix.token_strings[-1]
    prev = prefix.token_strings[-2] if len(prefix.token_strings) > 1 else ""
    if tok in TOPIC_WORDS:
        return carry, TOPIC_WORDS[tok]
    if tok in CAP_ABOUT:
        return carry, 1.2
    if tok in ABOUT_WORDS:
        return carry, 0.6
    if tok in FOR_WORDS:
        # Start of a line, a code block or a bracket: a loop or a new sentence-level phrase.
        if prev.strip() == "" or prev.endswith(("\n", "\t")) or prev in ("(", "{", "["):
            return carry, 0.75
        # After sentence-final punctuation: "For example", "As for ...".
        if prev[-1:] in ".!?\"'":
            return carry, 0.7
        # After a comma, colon or semicolon: a clause-level "for".
        if prev[-1:] in ",;:":
            return carry, 0.5
        # After a word: usually a verb or noun that takes "for" ("preparing for"), so low.
        return carry, 0.18
    return carry, TAGS.get(tok, 0.0)

programs.sol:
"""Approximate the strong local comparison and clause-linking responses.

The main triggers are 'as' and 'like', especially in 'same ... as', 'just
as/like', 'such as', and after clause punctuation. Comparative 'to' fires
after similarity words. Case and word boundaries, including identifier
separators, matter. Import aliases instead give a negative response; a
standalone tab gives a positive
formatting response. A 200-character tail, reset per document, is enough for
these rules. Small, unrelated lexical responses are left at zero.
"""
import re

READS = ()
SIMILARITY = {'identical', 'comparable', 'equivalent', 'analogous', 'akin'}
GEOMETRIC = {'parallel', 'opposite', 'adjacent', 'perpendicular', 'orthogonal'}


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    tail = '' if carry is None or carry[0] != doc else carry[1]
    token = prefix.token_strings[-1]
    stripped = token.strip(' \t\r\n._-/([\"\'“')
    word = stripped.lower()
    value = 0.0
    if token == '\t':
        value = 0.65
    elif word in {'as', 'like', 'unlike', 'to', 'about'}:
        words = re.findall(r'\w+', tail)
        previous = words[-1].lower() if words else ''
        recent = [w.lower() for w in words[-4:]]
        boundary = not tail or not tail[-1].isalnum() or token[0].isspace()
        clause = tail.rstrip().endswith((',', ';', ':', '–', '—'))
        if word == 'as':
            if stripped == 'AS':
                value = 0.4
            elif token[:1] in '._-':
                value = 1.5 if stripped == 'As' else 0.9
            elif stripped == 'As':
                value = 2.2 if not tail else 1.8 if boundary else 0.6
                if token.startswith(' ') and tail and tail[-1].isalnum():
                    value = 1.25
            elif token == 'as':
                value = 1.3 if previous == 'where' else 1.2 if boundary else 0.05
            elif re.search(r'\bimport\s+[\w.*]+$', tail):
                value = -1.0 if tail.endswith('*') else -2.0
            elif 'same' in recent:
                distance = recent[::-1].index('same')
                value = (3.3, 2.9, 2.1, 1.4)[distance]
            elif previous == 'just':
                value = 2.5
            elif previous == 'exactly':
                value = 1.9
            elif clause or previous in {'and', 'but'}:
                value = 1.3
            elif previous in {'such', 'not', 'inasmuch', 'insofar'}:
                value = 0.9
            elif previous in {'much', 'twice', 'thrice'}:
                value = 1.2
            else:
                value = 0.1
        elif word == 'unlike':
            value = 0.75
        elif word == 'like':
            if token != ' like':
                value = 0.7 if boundary else 0.3
            elif previous == 'just':
                value = 2.2
            elif previous in {'exactly', 'precisely'}:
                value = 1.5
            elif previous == 'much':
                value = 1.7
            elif clause or previous in {'and', 'but'}:
                value = 0.9
            elif previous in {'seem', 'seems', 'seemed', 'feel', 'feels', 'felt'}:
                value = -0.5
            else:
                value = 0.1
        elif word == 'to':
            if previous == 'similar':
                value = 3.2 if words[-1][0].isupper() else 2.2
            elif previous in SIMILARITY or previous == 'like':
                value = 1.0
            elif previous in {'equal', 'different', 'contrast', 'just'} | GEOMETRIC:
                value = 0.55
        elif word == 'about' and previous == 'just':
            value = 0.55
    return (doc, (tail + token).replace('\\n', '\n')[-200:]), value

programs.haiku:
"""Layer-0 MLP down_proj component 454: a "comparison" detector.

What it responds to, in plain terms:
- The word "as" when it opens a comparison or an equivalence: "the same ... as",
  "similar ... as", "just as", "such as", and ", as shown in" / "and as" / "not as".
  This is the strongest and most reliable response (about +3 after "same", +1.3 after
  a comma, +1 after "such"/"and"/"not").
- The word "to" after a similarity word: "similar to" (about +2.5), "identical to",
  "same ... to", and more weakly "equal to", "equivalent to" (about +0.7).
- The word "like" after "just" or "much" (about +2), and after a comma (about +0.9).
- Capitalised "As" (sentence start, or Visual Basic "Dim x As Range"): about +1.6.
- A literal tab character, which is code indentation: a steady +0.65.
- Negative: "as" in a Python import alias ("import numpy as np"), about -2; and a few
  punctuation and keyword tokens ("{", "$", "'", "than", "import"), about -0.1.

Everything else predicts 0. The numbers are average activations measured on training
text, not fitted to eval. A token-only table of averages explains about 0.39 of the
variance held out; these rules explain about 0.45 to 0.46 on training samples.
"""

READS = ()

# Words that signal "the same / similar as". A window of the last four tokens is checked.
SAMENESS = {"same", "Same", "similar", "Similar", "identical", "equal", "equivalent",
            "comparable"}
# Similarity words that are followed by a strong "to" ("similar to", "identical to").
STRONG_TO_LEAD = {"similar", "Similar", "identical", "same", "Same"}
# Words after which "as" or "like" is an ordinary comparison ("just as", "just like").
JUST_LIKE_LEAD = {"just", "Just", "much"}
# Words after which "as" is moderately strong ("such as", "and as", "not as").
AND_LEAD = {"and", "And", "but", "But", "not", "such"}
# Small negative tokens.
SMALL_NEGATIVE = {" {", " $", " '", " than", " import"}


def line_so_far(prefix):
    """The text of the current line, up to the token being predicted."""
    out = []
    for tok in reversed(prefix.token_strings[:-1]):
        if "\n" in tok:
            break
        out.append(tok)
    return "".join(reversed(out)).lstrip()


def step(carry, prefix, upstream):
    tok = prefix.token_strings[-1]
    prev = prefix.token_strings[-2].strip() if len(prefix) > 1 else ""
    recent = {s.strip() for s in prefix.token_strings[-5:-1]}

    if tok == "\t":
        return None, 0.65
    if tok in (" As", "As"):
        return None, 1.6
    if tok in (" as", "as"):
        if line_so_far(prefix).startswith(("import ", "from ")):
            return None, -2.0  # import alias: "import numpy as np"
        if recent & SAMENESS:
            return None, 2.8  # "the same ... as"
        if prev in JUST_LIKE_LEAD:
            return None, 2.6  # "just as"
        if prev == ",":
            return None, 1.3  # ", as shown in"
        if prev in AND_LEAD:
            return None, 1.0  # "such as", "and as", "not as"
        return None, 0.2  # other uses ("known as", "used as", "well as") are near zero
    if tok == " to" and prev in SAMENESS:
        return None, 2.5 if prev in STRONG_TO_LEAD else 0.7
    if tok == " like":
