    word = token.strip().casefold()
    previous = previous2 = previous3 = ""

    if within_document(prefix, 1):
        previous = prefix.token_strings[-2].strip().casefold()
    if within_document(prefix, 2):
        previous2 = prefix.token_strings[-3].strip().casefold()
    if within_document(prefix, 3):
        previous3 = prefix.token_strings[-4].strip().casefold()

    if "\t" in token and not word:
        if not previous:
            return None, 0.54
        if previous in {"{", "}", ";", ")", ":"}:
            return None, 0.4
        return None, 0.08

    if word == "as":
        if previous == "same" or previous2 == "same" or previous3 == "same":
            return None, 3.1
        if previous == "just":
            return None, 2.9
        if previous == "such":
            return None, 0.9
        if previous == "," or previous in {"and", "but"}:
            return None, 1.3
        if previous == ".":
            return None, 1.8
        if previous == "numpy" or previous2 == "import":
            return None, -1.0
        if token.strip() == "As":
