        return None, 0.3

    if word == "to":
        comparison_phrases = {
            "similar": 2.2,
            "like": 1.0,
            "equal": 0.6,
            "equivalent": 0.9,
            "opposite": 0.9,
            "different": 0.6,
            "compared": 0.27,
            "order": 0.28,
