    '适应': -3.2, '適應': -3.2, '適応': -3.2,
    '适': -1.4, '適': -1.3, '阿': -1.3,
    '采用': -1.0, '採用': -1.0, '采取': -0.77, '採取': -0.77,
    '收购': -1.2, '收購': -1.2, '放弃': -1.1, '放棄': -1.1,
    '广告': -0.8, '廣告': -0.8, '改变': -0.6, '改變': -0.6,
    '学术': -0.8, '學術': -0.8, '招生': -1.3,
    '信号': 1.4, '信號': 1.4,
}


def lexical_value(token):
    if token in CHINESE:
        return CHINESE[token]
    if token == '<think>':
        return -0.16
    if token == '</think>':
        return 0.15
    if token in {'</tool_call>', '<tool_response>'}:
        return 0.1
    if token == '</tool_response>':
        return 0.2
    if token == '<|im_end|>':
        return 0.08

    word = token.lstrip(' \t\r\n._/-(\"[')
    low = word.lower()
    boundary = len(word) < len(token)
    title = bool(word) and word[0].isupper() and not word.isupper()

    if low.startswith('signal'):
        if low.endswith(('ing', 'ed')):
