        return -0.12 if low == 'ac' else 0.0

    if 'adapter' in low:
        return -2.0 if not boundary and 'Adapter' in word else -1.6
    if low.startswith('adap'):
        if low.startswith(('adaptor', 'adaptable', 'adaptations')):
