"""Component layers.0.mlp.down_proj:456 — a "present-time / current" word detector.

What it does: this component writes a strongly negative value into the residual stream
when the current token is the word "current" (or a form of it: "Current", " current",
"currently", the Chinese 目前 / 当前 / 电流 for "at present" / "currently" / "electric current").
It writes a weaker negative value on words that point to a time relative to now
("previous", "prior", "former", "recent", "existing", "future", "latest", "already",
"another", "modern", ...). Everything else gets 0.

How it is read: the activation is the component's contribution at each token, so a
negative value means the component pushes the residual stream in the "current / recent
time" direction. Only the current token matters; the program needs no state.
"""

READS = ()

# Whole-word "current" in English and its Chinese counterparts.
CURRENT = {"current", "currents"}
CURRENTLY = {"currently", "目前", "当前", "电流"}

# Words that refer to a time relative to now (before, after, recent, or the newest one).
RECENCY = {
    "previous", "previously", "prior", "former", "recent", "recently", "existing",
    "latest", "future", "upcoming", "preceding", "presently", "ongoing", "already",
    "another", "modern", "contemporary", "active", "potential", "emerging",
    "前", "已", "以前", "之前", "未来", "最新", "现代",
}


def _word(token: str) -> str:
    """Lowercase letters only: ' Current', '(current' and '_current' all become 'current'."""
    return "".join(ch for ch in token.lower() if ch.isalpha() or "一" <= ch <= "鿿")


def step(carry, prefix, upstream):
    word = _word(prefix.token_strings[-1])
    if word in CURRENT:
        value = -5.5
    elif word in CURRENTLY:
        value = -4.0
    elif word in RECENCY:
        value = -1.0
    else:
        value = 0.0
    return None, value

