"""Recognize the lexical family of directness, directing and guidance.

The direct stem is strongest; related job titles, directions, directories,
guidance and commands are weaker. A small set of non-English equivalents
and secondary cues (straight, live, null) is included. Split-word endings and
immediate complements such as 'director of' keep a short contextual response.
The weights approximate training responses, not a general semantic rule.
Unrecognized tokens get zero. State resets at each document boundary.
"""
READS = ()

# Values distinguish inflections within a single recognizable word family.
DIRECT_FAMILY = {
    'direct': 6.65, 'directing': 6.65, 'directs': 7.2,
    'directly': 5.45, 'directed': 5.5,
    'irect': 4.5, 'irected': 4.2, 'irector': 2.3,
    'director': 3.0, 'directors': 2.55,
    'direction': 2.1, 'directions': 2.3, 'directional': 1.55,
    'directive': 3.1, 'directives': 4.1,
    'directory': 1.25, 'directories': 1.25, 'dir': 0.85, 'dirname': 0.85,
    'indirect': 2.0, 'indirectly': 1.6,
    'redirect': 3.0, 'redirects': 3.2, 'redirected': 1.6,
    'direkt': 3.5, 'diret': 3.0, 'dire': 1.2,
}
GUIDANCE = {'guide': 1.65, 'guides': 1.5, 'guided': 1.1,
            'guiding': 1.3, 'guidance': 1.1,
            'instruction': 1.0, 'instructions': 1.2}
COMMANDS = {'command', 'commands', 'commanding', 'commanded'}
DIRECT_ENDINGS = {
    'ly': 4.1, 'ed': 4.8, 'ing': 5.9, 's': 3.8,
    'ement': 3.5, 'amente': 2.5, 'a': 2.5, 'e': 2.7,
    'ive': 2.0, 'ives': 2.3, 'es': 2.4, 'iva': 0.9, 'ivas': 0.6,
    'eur': 0.9, 'o': 1.3, 'en': 1.2, 'or': 0.9, 'ors': 1.0,
    'ories': 0.6, 'rix': 0.7,
}


def lexical(token, word):
    if word in DIRECT_FAMILY:
        value = DIRECT_FAMILY[word]
        if word in {'direct', 'directing', 'directs'} and token[:1].isalpha():
            value += 0.75
        if word == 'direct' and token.strip() == 'Direct':
            value += 0.2
        if word == 'directive' and token.strip()[:1].isupper():
            value = 2.5
        return value
    # Romance directing stems and Russian 'direct/guide'.
    if word.startswith(('dirig', 'direc', 'направ')):
        return 1.4
    # Russian straight/direct and leadership; Polish directness.
    if word.startswith(('прям', 'руковод')):
        return 1.0
    if word.startswith('bezpoś'):
        return 2.7
    if word in GUIDANCE:
        return GUIDANCE[word]
    if word in COMMANDS:
        return 0.68 if token == 'command' else 0.95
    if word in {'conduct', 'conducted', 'conducting'}:
        return 0.7 if token.startswith(' ') else 0.3
    if word in {'address', 'addresses', 'addressed', 'addressing'}:
        return 0.68
    if word in {'straight', 'straightforward', 'null'}:
        return 0.7
    if word == 'live':
        return 0.6 if token == ' live' else 0.27
    # Chinese: directly, guiding/commanding, and directing a film.
    if word in {'直接', '可以直接'}:
        return 5.9 if word == '直接' else 4.5
    if word in {'指导', '指导下', '指挥'}:
        return 3.2
    if word in {'导演', '执导'}:
        return 2.8
    # Straight/direct and guide roots, then direction/hosting/live cues.
    if word in {'直', '导', '導', '指導', '引导', '引導', '导向'}:
        return 2.5 if word == '直' else 1.9
    if word in {'方向', '主持', '直播', '指引', '직'}:
        return 1.35
    # Korean 'directly'; smaller Chinese direction/command relatives.
    if word == '직접':
        return 3.8
    if word in {'令', '向', '引', '一直', '直线', '领导', '命令'}:
        return 0.7
    if word in {'接', '目录', '主任', '指令', '间接'}:
        return 1.3
    # Vietnamese direct and Arabic directly/live.
    if word in {'trực', 'مباشرة', 'المباشر'}:
        return 2.3
    return 0.0


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    doc = prefix.document_ids[-1]
    prev = '' if carry is None or carry[0] != doc else carry[1]
    word = token.strip().lstrip('_-./(,').lower()
    value = lexical(token, word)
    if prev == 'direct' and token.lower() in DIRECT_ENDINGS:
        value = DIRECT_ENDINGS[token.lower()]
    elif token == ' of' and prev in {'director', 'directors',
                                     'direction', 'directions'}:
        if prev == 'director':
            value = 1.6
        elif prev == 'direction':
            value = 1.2
        else:
            value = 0.95
    elif token == ' by' and prev == 'directed':
        value = 0.7
    elif token == ' the' and prev in {
        'direct', 'directs', 'directed', 'directing'
    }:
        value = 1.45 if prev == 'direct' else 1.1
    return (doc, word), float(value)

