ALREADY_WORDS = {"already", "уже", "早已", "đã", "telah", "déjà", "bereits", "już", "già", "すでに"}
CHINESE_ALREADY = {"已", "已经", "已是", "已在", "已有"}
BEEN_AFTER = {"has": -3.4, "'s": -3.4, "’s": -3.4, "have": -2.4, "had": -1.9}
WEAKER_MARKERS = {
    "previously", "formerly", "recently", "recent", "newly", "currently",
    "existing", "being", "'ve", "’ve", "先前", "先", "先行", "曾", "又",
    "未", "刚", "剛", "既", "被", "正在",
    "sido", "stato", "wurden", "wurde", "worden", "был", "была",
}


def value_for(token, previous):
    word = token.strip().lower()
    if word in ALREADY_WORDS:
        return -3.6
    if word in CHINESE_ALREADY:
        return -8.0
    if word == "been" or word == "été":
        return BEEN_AFTER.get(previous.strip().lower(), -2.8)
    if word in WEAKER_MARKERS:
        return -1.0
    return 0.0


def step(carry, prefix, upstream):
    previous = prefix.token_strings[-2] if len(prefix.token_strings) > 1 else ""
    return None, float(value_for(prefix.token_strings[-1], previous))

