# Columns: space, tab, nonbreaking space, backslash, space-backslash.
GAP_RESPONSE = {
    'start': (-0.82, -0.65, -0.55, 0.26, -0.20),
    'word': (0.04, -0.10, 0.07, 0.03, -0.01),
    'number': (-0.04, -0.06, -0.10, -0.04, -0.06),
    'comma': (-0.07, 0.02, 0.10, -0.06, -0.01),
    'period': (-0.69, -0.47, -0.67, -0.36, -0.25),
    'colon': (-0.81, -0.50, -0.26, -0.36, -0.32),
    'closing': (-0.48, -0.30, -0.34, -0.16, -0.25),
    'opening': (-1.08, -0.72, -0.66, -0.78, -0.51),
    'operator': (-0.90, -0.87, -0.55, -0.81, -0.59),
    'marker': (-1.26, -0.84, -0.66, -0.56, -0.63),
    'currency': (-0.74, -0.60, -0.44, -1.13, -0.66),
    'line': (-1.85, -0.95, -0.49, -0.54, -0.62),
    'gap': (-2.01, -0.76, -0.36, -0.74, -0.70),
    'other': (-0.61, -0.60, -0.51, -0.38, -0.30),
}
SINGLE_GAPS = {' ': 0, '\t': 1, '\xa0': 2, '\\': 3, ' \\': 4}

ENDING_CLASSES = {
    'comma': ',',
    'period': '.',
    'colon': ':',
    'closing': ')]}',
    'opening': '([{',
    'marker': '*|>#•',
    'operator': '=+-−–/&<>~^',
    'currency': '$€£¥₹',
}


def preceding_kind(s):
    if not s:
        return 'start'
    if s.endswith(('\n', '\r')):
        return 'line'
    if s.isspace():
        return 'gap'
    c = s[-1]
    if c.isalpha():
        return 'word'
    if c.isdigit():
        return 'number'
    for kind, characters in ENDING_CLASSES.items():
        if c in characters:
            return kind
    return 'other'


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    s = prefix.token_strings[-1]
    previous = carry[1] if carry is not None and carry[0] == doc else ''
    before_previous = carry[2] if previous else ''
    kind = preceding_kind(previous)
    value = 0.0
    if s in SINGLE_GAPS:
        value = GAP_RESPONSE[kind][SINGLE_GAPS[s]]
        if s == ' ':
            if previous and set(previous) == {' '}:
                n = len(previous)
                value = (-1.76, -2.08, -2.23, -2.01)[n - 1] if n <= 4 else (
                    -1.25 - 3.4 / (n + 1)
                )
            elif kind == 'gap':
                value = -1.1 if '\xa0' in previous else -1.0
            elif previous == '\\n':
                value = -0.95
            elif previous == 'n' and before_previous.endswith('\\'):
                value = -0.47
            elif kind == 'line':
                end = previous.rstrip()
                if end.endswith(','):
                    value += 0.28
                elif end.endswith('*'):
                    value -= 0.3
            elif kind == 'word' and not previous.startswith(' '):
                value = -0.03
    elif s and all(c == ' ' for c in s):
        n = len(s)
        scale = min(1.0, 7.0 / n)
        if kind == 'line':
            value = -0.55 * scale
            if previous.rstrip().endswith(','):
                value += 0.16 * scale
            elif previous.rstrip().endswith('*'):
                value -= 0.20 * scale
        elif kind in ('operator', 'marker', 'gap'):
            value = -0.25 * scale
        elif kind == 'number':
            value = 0.18 * scale
        else:
            value = 0.05 * scale
    elif s and all(c == '\t' for c in s):
        value = -0.9 / len(s) if kind in ('line', 'gap') else 0.03
    return (doc, s, previous), float(value)

