READS = ()

# Closing brackets, quotes and slashes: the space after them is weakly negative.
CLOSERS = {")", "]", "/", "%", '"', "'", " \"", " `", "`"}


def _is_space_run(s):
    """Spaces, tabs or no-break spaces, with no newline."""
    return s != "" and s.strip(" \t\xa0") == ""


def _has_newline(s):
    return "\n" in s or "\r" in s


def _has_word_char(s):
    return any(c.isalnum() for c in s)


def step(carry, prefix, upstream):
    cur = prefix.token_strings[-1]
    if cur.strip(" ") == "\\":
        return carry, -0.3
    if not _is_space_run(cur):
        return carry, 0.0
    if len(prefix.token_strings) < 2 or prefix.document_ids[-2] != prefix.document_ids[-1]:
        return carry, -0.4
    prev = prefix.token_strings[-2]
    if _is_space_run(prev):
        return carry, -2.0
    if prev.endswith(",") or (_has_word_char(prev) and not _has_newline(prev)):
        return carry, 0.0
    if prev in CLOSERS:
        return carry, -0.2
    return carry, -0.8

programs.luna:
"""Detect indentation-like whitespace in the current token.

The strongest negative response is a single space after whitespace; spaces after
punctuation also register, while ordinary word boundaries and line breaks are
mostly quiet.
"""
READS = ()


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    if not token or not token.isspace():
        return None, -0.003

    previous = ""
    if len(prefix.token_ids) > 1:
        if prefix.document_ids[-1] == prefix.document_ids[-2]:
            previous = prefix.token_strings[-2]
    last = previous[-1:] if previous else ""

    if all(char == " " for char in token):
        if len(token) == 1:
            if last.isspace():
                value = -2.0
            elif last and last.isascii() and not last.isalnum():
                value = -0.5
            elif last.isupper():
                value = 0.15
            elif last.isalpha():
                value = 0.03
            elif last.isdigit():
                value = -0.09
            else:
                value = -0.5
        elif last.isspace():
            value = -0.48
        elif last and last.isascii() and not last.isalnum():
            value = -0.16
        else:
            value = 0.0
    elif all(char == "\t" for char in token):
        if last.isspace():
            value = -0.88
        elif last.isdigit():
            value = -0.06
        else:
            value = -0.2
    elif all(char == "\xa0" for char in token):
        if last.isspace():
            value = -0.46
        elif last and last.isascii() and not last.isalnum():
            value = -0.65
        elif last.isdigit():
            value = -0.18
        else:
            value = 0.0
    else:
        value = 0.0
    return None, float(value)

programs.sol:
"""Lexical references to source code, files and programming constructs.

Code, file, snippet and patch-header words are strong negative cues. Source-code
modifiers strengthen 'code'; status/error/QR modifiers weaken it. Code quotation,
comments, declaration keywords and 'Here's' give smaller negative responses.
A few common translations receive the same kind of response. 'Exit', the URL
separator and line-ending backticks have positive responses. Unlisted text
predicts zero. Only the previous token is remembered, reset at each document;
this is not a code parser.
"""

READS = ()

LANGUAGES = set('python java javascript typescript ruby rust golang php c++ c#'.split())
POINTING = set('this that these those my your our its their his her'.split())
REVISIONS = set(
    'current original existing same modified updated clean efficient additional'.split()
)
NUMBER_CODES = set(
    'exit error status return response result zip postal area tax dress security '
    'promotion coupon discount redemption qr bar'.split()
)

TERMS = {
    'function': -0.45, 'functions': -0.2, 'func': -0.61,
    'callable': -0.6, 'method': -0.27, 'call': -0.5, 'calls': -0.44,
    'implementation': -0.8, 'implement': -0.28,
    'private': -0.43, 'protected': -0.25, 'override': -0.64,
    'def': -0.29, 'void': -0.26, 'static': -0.24, 'async': -0.4,
    'script': -0.35, 'program': -0.35, 'loop': -0.4,
    'syntax': -0.45, 'inline': -0.5, 'source': -0.23,
    'approach': -0.4, 'logic': -0.74, 'solution': -0.14,
    'correctly': -0.53, 'properly': -0.34, 'algorithm': -0.28,
    'changes': -0.25, 'coding': -0.61, 'called': -0.11,
    'line': -0.43, 'lines': -0.28, 'example': -0.22, 'examples': -0.18,
    '代码': -3.3, 'コード': -1.3, 'код': -1.3, 'código': -1.45,
    '코드': -2.3, '文件': -1.17, 'файл': -1.17, 'arquivo': -0.9,
    '函数': -0.84, '程序': -0.88,
}


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    before = '' if carry is None or carry[0] != doc else carry[1]
    token = prefix.token_strings[-1]
    word = token.strip().lstrip('_.(/-@').lower()
    spaced = token.startswith(' ')
    value = TERMS.get(word, 0.0)
    if word == 'code':
        value = -1.1
        if token == ' code':
            value = -2.35
            if before in NUMBER_CODES:
                value = -0.6
            elif before in LANGUAGES or before in {'following', 'driver'}:
                value = -4.45
            elif before in POINTING | REVISIONS:
                value = -3.55
            elif before in {'the', 'of', 'in'}:
                value = -3.05
            elif before in {'a', 'to'}:
                value = -1.75
        elif token == 'code' or token.startswith('_'):
            value = -0.82
        elif token.startswith('/'):
            value = -1.62
        elif token.startswith('-'):
            value = -1.92
    elif word == 'codes':
        value = -0.48
    elif word in {'file', 'files'}:
        value = -1.44 if spaced else -1.2
    elif word in {'snippet', 'snippets'}:
        value = -2.45 if spaced else -1.6
    elif word == 'example' and before == 'for':
        value = 0.02
    elif word == 'line' and before.endswith(('\",', "',")):
        value = -2.15
    elif word == 'exit':
        value = 0.43
    elif token in {"'s", '’s'} and before == 'here':
        value = -1.15
    elif token in {'.java', '/java'}:
        value = -0.5
    elif token == '://':
        value = 0.18
    elif token.strip() == '@@':
        value = -2.13 if '\n' in token else (-3.5 if spaced else -2.3)
    elif token.strip() == '+++':
        value = -1.49
    elif '`' in token and not token.strip(' `\t\n_'):
        n = token.count('`')
        if n >= 3:
            value = -0.69
        elif n == 2:
            value = -0.05
        else:
            value = 0.14 if '\n' in token else (-0.56 if spaced else -0.11)
    elif token.strip() == '//':
        value = -0.265
    elif token.strip() == '#':
        value = -0.205 if spaced else -0.12
    return (doc, token.strip().lower()), float(value)

programs.luna:
"""A lexical sketch of a code-and-documentation response.

The estimates center on ``code`` and ``file``, with smaller hits on
programming words and code marks.  A few system API names and ``main`` are
positive; ``following code`` and ``driver code`` get a stronger negative hit.
"""

READS = ()

_STRONG = {"code": -1.7, "file": -1.3, "files": -1.3, "sourcecode": -1.4}
_PROGRAMMING_WORDS = {
    "algorithm", "approach", "call", "called", "def", "func", "function",
    "functions", "implementation", "line", "lines", "listing", "loop",
    "method", "private", "program", "routine", "static", "void",
    "@override", "typescript",
}
_DOCUMENTATION_WORDS = {
    "above", "below", "changes", "example", "filename", "sample", "solution",
}
_CODE_MARKS = {"#": -0.17, "//": -0.27, "`": -0.24}
_SYSTEM_APIS = {"exit": 0.4, "malloc": 0.4, "main": 0.17}


def step(carry, prefix, upstream):
    word = prefix.token_strings[-1].strip().lower()
    previous = prefix.token_strings[-2].strip().lower() if len(prefix) > 1 else ""
    if word == "code" and previous in {"following", "driver"}:
        return None, -4.5
    if word in _STRONG:
        return None, _STRONG[word]
    if word in _PROGRAMMING_WORDS:
        return None, -0.4
    if word in _DOCUMENTATION_WORDS:
        return None, -0.25
    if word in _CODE_MARKS:
        return None, _CODE_MARKS[word]
    if word in _SYSTEM_APIS:
        return None, _SYSTEM_APIS[word]
    return None, 0.0

programs.sol:
"""A decimal-digit continuation detector with a calibrated response size.

Second and later digits fire strongly; third and fourth digits fire somewhat
more. The adjacent digits' values and the preceding digit's parity modulate
the strength. A digit at a document start also fires. Fullwidth decimal
digits are treated as their ordinary counterparts. All other tokens get a
small background value. The coefficients are fitted on training text.
"""
READS = ()

def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    new_document = carry is None or carry[0] != doc
    _, run, previous = (doc, 0, -1) if new_document else carry
    token = prefix.token_strings[-1]
    if len(token) == 1 and '０' <= token <= '９':
        token = chr(ord('0') + ord(token) - ord('０'))
    if len(token) != 1 or token not in '0123456789':
        return (doc, 0, -1), 0.003

    digit = int(token)
    if new_document:
        value = 1.70
    elif run == 0:
        value = -0.012
    else:
        # A smoothly varying gain, with different slopes for even and odd
        # preceding digits. Zero, one, and two have distinct low-digit gains.
        p = previous
        value = 0.673 + 0.185 * p - 0.0107 * p * p
        if p == 0:
            value += 0.608
        elif p == 1:
            value += 0.535
        elif p % 2 == 0:
            value += 0.525 - 0.0713 * digit
            if p == 2:
                value += 0.229 - 0.0929 * digit
        else:
            value += 0.0424 * digit
        if digit == 0:
            value += 0.178
        elif digit == 1:
            value += 0.150
        elif digit == 8:
            value += 0.095
        if run == 2:
            value += 0.287
        elif run == 3:
            value += 0.240
        elif run >= 4:
            value += 0.081
    return (doc, run + 1, digit), float(value)

programs.luna:
"""Flag later digits in a written numeral; the first digit starts it."""
import unicodedata

READS = ()


def is_digit(ch):
    return unicodedata.category(ch) == "Nd"


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    previous_doc, previous_char = carry or (None, "")
    if doc != previous_doc:
        previous_char = ""
    token = prefix.token_strings[-1]
    # A continuation digit is preceded by another decimal digit, even
    # when the tokenizer puts several digits in one token.
    joined = previous_char + token
    fires = any(
        is_digit(joined[i]) and is_digit(joined[i - 1])
        for i in range(1, len(joined))
    )
    last = token[-1:] if token else ""
    return (doc, last), (1.6 if fires else 0.0)

programs.sol:
"""Approximate the negative lexical response to crime and law vocabulary.

Selected word families, mainly English and Chinese, get typical negative
values. A strong legal cue in the preceding four tokens makes another direct
legal cue slightly stronger. Two-token word completions are recognized, with
short suffixes weaker than whole words. Side rules cover location/extent and
possibility words, SQLite/deprecation name fragments, and a conversation
marker at document start with its following role. This is a lexical
approximation, not a judgment that an actual crime occurred; most other
word-specific baseline variations are left near zero.
"""

READS = ()

LEGAL_TERMS = set('''laws statute statutes regulations guilty indictment
illegal illegally illicit offender offenders enforcement arrests homicide
homicides aggravated violation violations pardon liability prohibition'''.split())
LIGHT_LEGAL_TERMS = set('''law arrest arrested sheriff jail jailed burglary
murder punish punished punishment'''.split())


def legal_value(word):
    if word in {'misdemeanor', 'felon', 'impunity'}:
        return -0.85
    if word in {'conviction', 'criminals'}:
        return -0.60
    if word == 'criminal':
        return -0.44
    if word == 'crimes':
        return -0.35
    if any(root in word for root in ('crime', 'criminal', 'convict', 'felon')):
        return -0.53
    if word in {'legislation', 'legislators', 'incarceration'}:
        return -0.52
    if word.startswith(('legisl', 'prosecut', 'imprison')):
        return -0.39
    if word in {'offense', 'offence', 'offences', 'offenses', 'outlaw',
                'lawmakers', 'subparagraph', 'amnesty', 'murderer'}:
        return -0.40
    if word in LEGAL_TERMS or word in {'incarcerated', 'suç', 'tội'}:
        return -0.27
    if word in LIGHT_LEGAL_TERMS:
        return -0.15
    if word in {'犯罪', '违法行为'}:
        return -0.90
    if '罪' in word or word in {'违法', '立法', '刑事'}:
        return -0.62
    if '公安' in word or word in {'法治', '法律法规', '法律责任',
                                 '受贿', '拘', '逮捕', '行政处罚'}:
        return -0.42
    if word in {'执法', '涉嫌', '处罚', '刑', '法定', '法规', '侵犯',
                '治安', '偷', '诈骗', '违纪'}:
        return -0.30
    if word in {'警方', '案件', '举报', '侵权', '罰'}:
        return -0.22
    if word in {'司法', '依法', '犯'}:
        return -0.15
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        position, previous, recent_legal = 0, '', ()
    else:
        position, previous, recent_legal = carry[1] + 1, carry[2], carry[3]
    raw = prefix.token_strings[-1]
    word = raw.strip().lower()
    prior = previous.strip().lower()
    value = legal_value(word)
    direct = value
    if value == 0.0 and raw.isalpha():
        value = legal_value(prior + word)
        value *= 0.5 if len(word) <= 3 else 0.85
    if direct < -0.2 and any(recent_legal):
        value -= 0.08
    recent_legal = (recent_legal + (direct < -0.2,))[-4:]
    if value == 0.0:
        value = 0.001

    if (prior, word) == ('convicted', 'of'):
        value = -0.21
    elif word == 'of' and prior in {'laws', 'guilty'}:
        value = -0.10
    elif prior == 'criminal' and word in {'justice', 'activity'}:
        value = -0.25
    elif word in {'anywhere', 'somewhere', 'elsewhere', 'everywhere', 'nowhere'}:
        value = -0.19
    elif word in {'almost', 'whole', 'altogether', 'entire', 'entirely'}:
        value = -0.11
    elif word in {'possible', 'possibly', 'possibility', 'possibilities', 'likely'}:
        value = 0.08
    # Capitalized annotation name and two SQLite Android name endings.
    elif raw in {'Deprecated', ' Deprecated'}:
        value = -0.40 if raw == 'Deprecated' else -0.17
    elif raw == 'iteDatabase':
        value = -0.66
    elif raw == 'OpenHelper':
        value = -0.28

    if position == 0 and raw == '<|im_start|>':
        value = 0.272
    elif position == 1 and previous == '<|im_start|>':
        if raw == 'user':
            value = 0.226
        elif raw == 'assistant':
            value = 0.171
    return (doc, position, raw, recent_legal), float(value)

programs.luna:
"""Predicts a small negative pulse for crime/law vocabulary and a positive one at user-turn starts."""
READS = ()

CRIME_WORDS = (
    "crime", "criminal", "convict", "felon", "misdemeanor", "offen",
    "prosecut", "prison", "penal", "murder", "robber", "theft", "fraud",
    "indict", "illegal", "impun",
)
LAW_WORDS = ("legislat", "regulation", "arrest")
CHINESE_CRIME = ("罪", "刑", "犯", "公安", "检察", "罚")


def parts(text):
    return tuple(piece.strip(".,;:!?\"'()[]{}<>_-/") for piece in text.split())


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1].lower().strip()
    previous, old_doc = ("", None) if carry is None else carry
    doc = prefix.document_ids[-1]
    if old_doc != doc:
        previous = ""

    if token == "<|im_start|>":
        value = 0.27
    elif token == "user" and previous == "<|im_start|>":
        value = 0.23
    else:
        words = parts(token)
        if any(word.startswith(stem) for word in words for stem in CRIME_WORDS):
            value = -0.5
        elif any(word.startswith(stem) for word in words for stem in LAW_WORDS):
            value = -0.3
        elif token in ("law", "laws"):
            value = -0.3
        elif any(stem in token for stem in CHINESE_CRIME):
            value = -0.5
        else:
            value = 0.0

    return (token, doc), value * 0.38

programs.sol:
"""Detect web-address introductions and related markup, using local link cues.

http/https receive by far the largest negative values, with weaker responses
for capitalized names, protocol-prefixed identifiers, and punctuation-bound
spellings. www, URL/URI, web file extensions, and link markup respond less.
Reference words and line/link boundaries strengthen plain protocols; quotes
weaken them. Most text is zero. Only adjacent tokens in one document are used.
"""

import re

READS = ()


def lexical(token):
    text = token.strip()
    word = re.sub(r'^[\W_]+', '', text)
    low = word.lower()
    leading = text[:len(text) - len(word)]
    value = 0.0

    if low.startswith('http'):
        protocol = 'https' if low.startswith('https') else 'http'
        name = word[:len(protocol)]
        if name.isupper():
            value = -5.1 if protocol == 'https' else -4.1
        elif name[0].isupper():
            value = -6.3
        else:
            value = -11.4 if protocol == 'https' else -10.0
            if token.startswith(' '):
                value -= 0.45 if protocol == 'https' else 0.3
        if leading:
            scale = 0.75
            if leading[-1] == ':':
                scale = 1.0
            elif leading[-1] == '_':
                scale = 1.25 if name.isupper() else 0.6
            elif leading[-1] == '\\':
                scale = 0.65
            value *= scale
        elif token.startswith('\t'):
            value *= 0.8
        if len(word) > len(protocol):
            value *= 0.42
    elif low == 'www':
        value = -1.5 if word.isupper() else -3.8
        if token.startswith(' ') and not word.isupper():
            value = -4.8
        if leading:
            value = -3.2
    elif low.startswith('url') or word.endswith('Url'):
        value = -1.25 if low in ('url', 'urls') else -0.9
        if low == 'urllib':
            value = -1.6
    elif low in ('uri', 'uris'):
        value = -0.65 if word.isupper() else -0.4
    elif text == '://':
        value = -0.82
    elif text in ('](', '![', '[]('):
        value = -0.4
    elif text == '<tool_call>':
        value = -0.5
    elif text == '.html':
        value = -1.55
    elif text == '.jpg':
        value = -0.9
    elif text == '.json':
        value = -0.68
    elif low == 'html':
        value = -0.82
    elif low in ('wikipedia', 'doi', 'mailto'):
        value = -2.5 if leading or low != 'wikipedia' else -1.1
    elif low == 'github':
        value = -0.55 if leading == '.' or token.startswith(' ') else -0.1
    elif low in ('youtube', 'webpage'):
        value = -0.5
    elif low == 'website':
        value = -0.25
    return value


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    previous = ''
    if len(prefix.token_strings) > 1:
        if prefix.document_ids[-1] == prefix.document_ids[-2]:
            previous = prefix.token_strings[-2]
    value = lexical(token)
    text = token.strip()
    p = previous.strip()
    if text in ('http', 'https'):
        if not previous:
            value = -6.7
        else:
            if p == 'See':
                value -= 2.6
            elif p == 'see':
                value -= 1.5
            elif p.lower() in ('at', 'from', 'visit', 'via'):
                value -= 1.0
            quoted = any(c in p for c in '\'"`')
            if quoted:
                value += 0.7 - (0.4 if '=' in p else 0.0)
            if '\n' in previous:
                value -= 1.0
            if '<' in p and not quoted:
                value -= 1.9
    elif text == 'www' and previous == '://':
        value = -2.65
    return None, float(value)

programs.haiku:
"""Web-address opener detector (v2): the component is pushed strongly negative on
the token that opens a web address ('http', 'https', 'www'), most of all in lowercase,
less in capitals, and weakly on url-ish words and '://'."""

READS = ()


def step(carry, prefix, upstream):
    s = prefix.token_strings[-1].strip()
    w = s.lower()
    if "http" in w:
        if s.islower():
            v = -10.0      # http, https, /http, -http, .http
        elif s.isupper():
            v = -4.5       # HTTP, HTTPS
        else:
            v = -7.0       # Http
    elif w == "www":
        v = -4.0 if s.islower() else -2.0
    elif w in ("url", "urls", "uri", "urn"):
        v = -1.3
    elif w == "://":
        v = -0.7
    else:
        v = 0.0
    return carry, v

programs.luna:
"""Recognize URL prefixes and familiar web-reference labels on the current token.
URL protocols and host prefixes are strongly negative; labels get smaller
negative values, and unrelated tokens get zero."""
import re

READS = ()


def step(carry, prefix, upstream):
    text = prefix.token_strings[-1].lower()
    raw = prefix.token_strings[-1]
    words = set(re.findall(r"[a-z]+", text))
    spelling = raw.strip()

    protocol = re.search(r"(?<![a-z])https?", text)
    if protocol:
        exact = raw[protocol.start():protocol.end()]
        if exact.lower() == "https":
            value = -13.0 if raw[:1].isspace() else -11.5
        elif exact == "HTTP":
            value = -4.5
        elif exact == "Http":
            value = -6.3
        elif raw.startswith("\t"):
            value = -7.6
        elif raw.startswith(" "):
            value = -10.3
        else:
            value = -7.0
        return None, value
    if "www" in words:
        return None, -5.0
    if "://" in text:
        return None, -0.55
    if "url" in words:
        return None, -1.25
    if "uri" in words or "urn" in words:
        return None, -0.5
    if "webpage" in words:
        return None, -0.5
    if "website" in words:
        return None, -0.35
    if "youtube" in words:
        return None, -0.6
    if "github" in words:
        return None, -0.6
    if "posted" in words:
        return None, -0.8
    if "published" in words:
        return None, -0.3
    if "copyright" in words:
        return None, -0.4
    if "<tool_call>" in text:
        return None, -0.5
    if words & {"jpg", "jpeg", "png"}:
        return None, -1.0
    if "html" in words:
        return None, -0.7
    if "](" in text:
        return None, -0.35
    if "网址" in text:
        return None, -1.2
    return None, 0.0

programs.sol:
"""A lexical detector for repetition and event frequency.

'Repeat' forms and 'again' dominate. Frequency, copying, looping and event
words give weaker positive responses. A short word-in-progress handles
split words; the signal also follows 'repeat the ...' and 'frequency of ...'.
It does not count actual repeated text, and omits unrelated small responses.
"""
READS = ()

REPETITION = {
    'repeat': 8.2, 'repeats': 7.15, 'repeated': 6.35, 'repeating': 6.65,
    'peated': 7.5, 'peating': 7.0, 'peats': 6.8,
    'again': 2.93, 'repeatedly': 3.55, 'repetition': 3.6,
    'repetitive': 3.75, 'repetitions': 2.8, 'repe': 2.4, 'repet': 3.0,
}
FREQUENCY = {
    'twice': 1.55, 'every': .92, 'once': .62, 'times': .56,
    'often': .82, 'frequent': 1.1, 'frequently': 1.0, 'frequency': .74,
    'regular': .57, 'regularly': .82, 'sometimes': .5, 'rarely': .35,
    'occasionally': .55, 'periodic': .5,
}
RELATED = {
    'multiple': .93, 'multiples': .7, 'double': .7, 'doubled': .7,
    'loop': 1.0, 'loops': 1.0, 'looping': 1.0,
    'pattern': .7, 'patterns': .44, 'cycle': .55, 'cycles': .36,
    'sequence': .46, 'consecutive': .57,
    'reverse': .63, 'opposite': .48,
    'alternate': .75, 'altern': .85, 'alternating': 1.07,
    'iter': .65, 'iterate': 1.1, 'iterator': .44, 'iterative': .59,
    'iterates': 1.45, 'iterated': 1.3, 'iterating': 1.3,
    'recurring': 1.9, 'recurrent': 1.2, 'recurrence': .9,
    'reiterated': 1.5, 'rep': .55, 'clone': .6,
}
# Some common translations and repetition/frequency morphemes.
TRANSLATIONS = {
    '重复': 6.05, '反复': 3.23, '重': .9, '复': 1.4, '復': 1.2,
    '複': 1.05, '屡': 1.65, '再次': 1.4, '多次': 1.3, '一遍': 1.5,
    '遍': .7, '一次': .6, '次': .4, '次数': .68, '倍': .85,
    '循环': 1.07, '频': 1.0, '頻': 1.15, '频繁': 2.0, '常常': .8,
    '何度も': 1.5, '复制': 1.3, '频频': 1.45, '经常': 1.0,
    'повтор': 4.85, 'снова': 1.2, 'часто': .93,
    'wieder': 1.2, 'häufig': .7, 'souvent': .49, 'fois': .43,
}
RECURRENCE_NOUNS = set('''frequency frequencies occurrence occurrences
    recurrence duplication replication timing'''.split())
REPEAT_VERBS = set('repeat repeats repeated repeating repetition'.split())


def lexical_score(word):
    for words in (REPETITION, FREQUENCY, RELATED, TRANSLATIONS):
        if word in words:
            return words[word]
    # Inflections and tokenized roots of familiar word families.
    if word.startswith('replic'):
        if word in {'replicating', 'replicates'}:
            return 2.8
        if word == 'replicate':
            return 2.1
        if word in {'replica', 'replicas'}:
            return .95
        return 1.25 if word == 'replication' else 1.6
    if word.startswith('duplic') or word == 'dup':
        if word in {'duplicate', 'duplicated', 'duplicating'}:
            return 2.1
        return 1.4
    if word.startswith('repro') or word.startswith('replay'):
        return .5 if word == 'reproduction' else 1.0
    if word.startswith('occur'):
        return .6 if word.startswith('occurrence') else .75
    if word.startswith('happen'):
        return .83
    if word.startswith('appear'):
        return .18 if word in {'appearance', 'appearances'} else .56
    return 0.0


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    doc = prefix.document_ids[-1]
    previous = carry[1] if carry is not None and carry[0] == doc else ''
    word = token.strip().lstrip('._-/(').lower()
    value = lexical_score(word)
    # Calibrate capitalization and code-identifier spelling of 'repeat'.
    if word == 'repeat':
        if 'Repeat' in token:
            value = 9.4
        elif token.startswith('_') and not token.isupper():
            value = 5.7
        elif token.startswith('-'):
            value = 6.95
        elif not token.startswith(' '):
            value = 7.75
    if token and token[0].isalpha() and previous:
        joined = previous + word
        if not value:
            value = lexical_score(joined)
            if previous.startswith('повтор'):
                value = 2.0
        if joined.isalpha() and len(joined) <= 32:
            word = joined
    if token == 'iter':
        value = .11
    if token == 'times':
        value = .21
    if token.startswith(' ') and previous in REPEAT_VERBS:
        if word == 'of':
            value = 3.8
        elif word == 'the':
            value = 2.0
        elif word in {'this', 'it', 'itself', 'his', 'your', 'my'}:
            value = 1.1
    elif word == 'of' and previous in RECURRENCE_NOUNS:
        value = 1.05
    return (doc, word), float(value)

programs.luna:
"""A small lexical detector for recurrence and frequency language.

This component tends to respond when a token names something happening again,
regularly, or more than once. Strong recurrence words get a larger prediction;
ordinary frequency and multiplicity words get a modest one. Most other tokens
are predicted as zero.
"""

READS = ()

STRONG_RECURRENCE = {
    "again", "repeatedly", "repetition", "repeat", "repeats",
    "repeated", "recurrence", "recur", "recurs", "recurring",
    "over-and-over",
}
FREQUENCY_OR_MULTIPLICITY = {
    "every", "each", "often", "frequent", "frequently", "frequency",
    "regular", "regularly", "occur", "occurs", "occurred", "occurring",
    "happen", "happens", "happened", "once", "twice", "double",
    "multiple", "many", "several", "numerous", "series", "cycle",
    "cyclic", "altern", "alternating", "alternately", "daily", "weekly",
    "monthly", "times", "time", "per", "rebuild", "redo",
    "次", "次数", "一次", "屡", "fois",
}


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1].strip().strip(".,;:!?()[]{}\"'").lower()
    # The activation can also rise on "of" immediately after a word such as
    # "repetition" or "series", as in "repetition of a word".
    previous = "" if carry is None or carry[0] != prefix.document_ids[-1] else carry[1]
    if token == "of":
        if previous in {"repetition", "repeat", "repeated", "series"}:
            value = 2.7 if previous == "repetition" else 0.6
        elif previous == "habit":
            value = 0.4
        else:
            value = 0.0
    elif token in STRONG_RECURRENCE:
        value = 2.7
    elif token in FREQUENCY_OR_MULTIPLICITY:
        value = 0.7
    else:
        value = 0.0
    return (prefix.document_ids[-1], token), float(value)

programs.sol:
"""Sparse cues of web publishing, documents and free downloadable material.

Recognize multilingual site/editor words, domains, credits and split compounds.
A 100-character tail supplies URL, copyright and document-editing context.
Generic English web/content terms are weakly negative. Other words receive
only a small script-dependent background prediction; most background variation
is deliberately not reproduced.
"""
import re
from functools import lru_cache

READS = ()
DOMAINS = set(
    'com org net edu gov io co cn ru uk de fr jp info biz tv me'.split()
)
FREE = {'бесплатно', 'gratuit', 'gratis', 'gratuite', '無料', '免费', '免費'}
PUBLISHERS = {'blog', 'blogs', 'editor', 'posts', 'docs'}
# Each group is a recognizable word class, with one approximate response.
GROUPS = (
    (0.75, {'小编', '小編', '今天小编'}),                 # editors
    (0.58, {'手机版', '手機版', '大全'}),               # mobile editions / compilations
    (0.35, {'网友', '網友', '本网', '本網'}),           # site contributors
    (0.25, {'版权', '版權', '转载', '轉載', '投稿', '收集', '搜集'}),
    (0.19, {'编辑', '編輯', '整理', '本文'}),
    (0.35, {'文档', '文檔'}),                           # documentation
    (0.14, {'网', '網', '版'}),                         # web / edition
    (0.20, {'бесплатно', 'gratuit', '無料', '免费', '免費'}),
    (0.04, {'gratis', 'gratuite'}),                    # free (Romance languages)
    (0.15, {'скачать', '下载', '下載'}),                # download
    (0.13, {'blog', 'blogs', 'editor', 'posts', 'docs'}),
    (-0.10, {'web', 'website', 'email', 'access', 'interface', 'request'}),
    (-0.07, {'content', 'information', 'index', 'directory', 'format', 'related'}),
)
WORDS = {word: value for value, group in GROUPS for word in group}


@lru_cache(maxsize=16384)
def background(s):
    w = s.strip()
    if w in WORDS:
        return WORDS[w]
    if w.lower() in WORDS:
        return WORDS[w.lower()]
    if any('\u3040' <= c <= '\u30ff' for c in w):
        return 0.025
    if any('\u4e00' <= c <= '\u9fff' for c in w):
        return 0.01
    return 0.001


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    first = carry is None or carry[0] != doc
    tail = '' if first else carry[1]
    s = prefix.token_strings[-1]
    w = s.strip()
    lo = w.lower()
    value = background(s)
    if lo.startswith('.') and lo[1:] in DOMAINS:
        url = any(cue in tail[-80:] for cue in ('://', 'www', '@'))
        value = 0.04 + 0.12 * url
        if lo == '.ru':
            value = 0.4 + 0.15 * url
        elif lo == '.cn':
            value = 0.25
        elif lo == '.io':
            value += 0.07
        if re.search(r'(blog|wordpress|docs?|library)[\w.\-/]*$', tail.lower()):
            value += 0.25
        if tail.lower().endswith('.blogspot'):
            value = 0.80
        if 'wikipedia' in tail[-40:].lower():
            value = -0.12
        if first:
            value = 0.9 if lo == '.com' else value + 0.25
    elif lo.strip(',-.') == 'www':
        value = 0.5 if first else (0.0 if s.startswith(' ') else 0.07)
    elif w in {'本站', '本网站', '本網站'}:
        value = 0.85 if w == '本站' else 0.35
    elif w in {'库', '庫'}:
        value = 0.85 if tail.endswith('文') else 0.12
    elif w == '编辑' and '文档' in tail[-25:]:
        value = 0.85
    elif w in {'整理', '分享', '为大家'} and '小编' in tail[-20:]:
        value = 0.85
    elif w in {'phí', 'viện'}:
        if tail.lower().endswith('miễn' if w == 'phí' else 'thư'):
            value = 0.5
    elif w in {'x', '-files'} and tail.endswith('doc'):
        value = 0.5
    elif lo in {'doc', 'docs', 'resource', 'resources', 'documents'}:
        value = 0.5 if first else (0.18 if lo == 'doc' else value)
    elif w in {'免费', '资源', '資料'} and first:
        value = 0.9
    elif lo in FREE:
        if first:
            value = 0.7 if w == '無料' else 0.5
        if any(cue in tail[-45:] for cue in ('скачать', 'абсолютно', '在线', '观看')):
            value += 0.35
    elif lo == 'reserved':
        credited = 'rights' in tail[-30:].lower()
        value = (0.55 if w == 'Reserved' else 0.25) if credited else 0.05
    elif lo == 'powered':
        value = 0.4 if s == ' Powered' else -0.13
    elif lo == 'by' and tail.endswith(' Powered'):
        value = 0.3
    elif lo in {'tagged', 'verified'}:
        credit = 'Resources' in tail[-40:] or 'expert-' in tail[-15:]
        value = 0.55 if credit else 0.04
    elif lo in {'download', 'downloads'}:
        value = 0.08 if s == ' Download' else 0.04
    elif lo in {'下载', '下載'} and first:
        value = 0.8
    elif lo in PUBLISHERS:
        value = 0.14 if s.startswith(' ') or w.istitle() else 0.04
    elif lo == 'of' and re.search(
        r'\b(copy|photos?|manuscript|courtesy)$', tail, re.IGNORECASE
    ):
        value = 0.17
    elif lo == 'free':
        value = 0.24 if first else -0.035
    elif lo in {'page', 'pages'}:
        value = 0.48 if first and s == ' Page' else -0.025
    elif '://' in s:
        value = 0.07
    elif lo in {'.html', '.htm', '.pdf', '.doc', '.docx'}:
        value = 0.09
    return (doc, (tail + s)[-100:]), float(value)

programs.luna:
"""Approximate a sparse web-page boilerplate feature.

Its strongest sampled responses are on site labels, free/download language,
domain endings, and recurring footer or page labels. These are weak cues:
recognized terms get small positive values; other text gets zero.
"""

READS = ()

SITE_WORDS = {"本站", "本网站", "網站", "网站", "小编", "小編"}
DOWNLOAD_WORDS = {"下载", "下載"}
FREE_WORDS = {"免費", "免费", "無料", "gratis", "free", "phí",
              "бесплатно", "бесплатный"}
SITE_LABELS = {"手机版", "大全"}
DOMAIN_ENDINGS = {".com", ".cn", ".io", ".ru", ".ag", ".net", ".org"}
FOOTER_WORDS = {"reserved", "powered"}
COPYRIGHT_WORDS = {"rights", "copyright", "版权", "版權"}
PAGE_LABELS = {"page", "tagged", "verified", "kids"}


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    old_doc, tail = carry if carry is not None else (doc, "")
    if doc != old_doc:
        tail = ""

    raw = prefix.token_strings[-1]
    word = raw.strip().casefold()
    next_tail = (tail + raw)[-100:]

    if word in SITE_WORDS:
        value = 0.8 if word in {"本站", "本网站", "網站", "网站"} else 0.65
    elif word in DOWNLOAD_WORDS:
        value = 0.75
    elif word in FREE_WORDS:
        value = 0.65
    elif word in DOMAIN_ENDINGS:
        value = 0.65
    elif word == "www":
        value = 0.5
    elif word in FOOTER_WORDS:
        value = 0.6 if word == "reserved" else 0.58
    elif word in COPYRIGHT_WORDS:
        value = 0.2
    elif word in PAGE_LABELS:
        value = 0.48 if word == "page" or word == "kids" else 0.58
    elif word in SITE_LABELS:
        value = 0.65
    elif "收集" in tail and word == "于":
        value = 0.58
    elif tail.endswith("doc") and word in {"x", "-files"}:
        value = 0.58
    elif "powered" in tail.casefold() and word == "by":
        value = 0.3
    elif "本站" in tail and word == "所有":
        value = 0.45
    else:
        value = 0.0

    return (doc, next_tail), float(value * 0.1)

programs.sol:
"""Approximate a multilingual B-spelling / B-sound response.

Predict a negative contribution for initial B, especially short spelling
fragments and capitals, and a weaker one for internal B. Treat Cyrillic
б, Arabic ب, Greek beta, Japanese B syllables, Korean ㅂ/ㅃ syllables and
some Mandarin b-initial characters similarly. Familiar words have weaker,
word-specific strengths. Modal/infinitive contexts weaken English "be";
division/multiplication cues and preceding words ending in -ed weaken
"by". A trailing B affects the next attached token; a further B there is
suppressed. Closing a tool call is a separate positive response. State
is reset at each document boundary.

This is a coarse spelling rule, not a complete account of lexical or
non-B activations; most other tokens are predicted as zero.
"""
import unicodedata

READS = ()

# Grammatical B-words are less like a standalone letter or name fragment.
GRAMMATICAL = {
    'been': 0.16, 'being': -0.78,
    'but': -1.14, 'because': -0.46,
    'before': -0.80, 'between': -0.74, 'both': -0.66,
    'below': -0.60, 'behind': -1.16, 'beyond': -1.54,
    'become': -0.78, 'becomes': -0.72, 'became': -0.40,
}
MANDARIN_B = frozenset(
    '掰八巴吧把爸拔罢罷坝壩霸白百摆擺败敗拜班般板版办辦半伴'
    '帮幫邦棒包胞薄饱飽宝寶保报報抱豹暴爆杯悲碑北贝貝倍'
    '背备備被奔本笨崩甭逼鼻比彼笔筆鄙币幣必毕畢闭閉碧壁'
    '避臂边邊编編扁便变變辨辩辯遍标標表彪别別宾賓冰兵饼'
    '餅并並病拨撥波玻剥剝伯泊勃博搏膊卜补補捕哺不布步部'
)


def b_sound(c):
    if c.lower() in 'bбβبばびぶべぼバビブベボ':
        return True
    k = ord(c) - 0xac00
    return 0 <= k < 11172 and k // 588 in (7, 8)


# Familiar short words and common word endings are not name fragments.
SHORT_WORDS = frozenset('bar bit big bob box boy bug bus buy bye'.split())
ENDINGS = frozenset('ber bers ben bes ble bles bly bs'.split())
MODALS = frozenset('can could may might must would'.split())
FUTURE_OR_ADVICE = frozenset('will shall should'.split())
FOREIGN_FUNCTION = frozenset('bei bien bon bom bene'.split())
ADVERBS = frozenset('also only always never still then even ever now not'.split())


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        previous, recent_modal = '', 0
    else:
        _, previous, recent_modal = carry
    raw = prefix.token_strings[-1]
    s = unicodedata.normalize('NFKC', raw)
    letters = ''.join(c for c in s if c.isalpha())
    prior = previous.strip().lower()
    value = 0.0
    if letters:
        first = letters[0]
        lower = letters.lower()
        if first.lower() == 'b':
            if lower in GRAMMATICAL:
                value = GRAMMATICAL[lower]
                if first.isupper():
                    value -= 0.25
            elif lower in SHORT_WORDS:
                value = -1.7 - 0.2 * first.isupper()
            elif lower in FOREIGN_FUNCTION and first.islower():
                value = -1.4
            elif lower in ENDINGS and first.islower() and not raw.startswith(' '):
                value = -0.9
            elif lower.startswith(('begin', 'began', 'begun')):
                value = -0.55
            elif lower.startswith('better'):
                value = -1.0
            elif lower.startswith('back'):
                value = -1.2
            elif lower.startswith('bottom'):
                value = -0.85
            elif lower.startswith(('book', 'body', 'build')):
                value = -1.25 - 0.2 * first.isupper()
            elif len(letters) == 1:
                value = -2.15 - 0.15 * first.isupper()
            elif len(letters) <= 3:
                vowel = letters[1].lower() in 'aeiou'
                value = -2.8 if vowel else -2.1
                if first.isupper() and not letters.isupper():
                    value -= 0.25
            else:
                value = -1.65 - 0.55 * first.isupper()
            if lower == 'be':
                value = -1.6
                if raw.startswith(' ') and first.islower():
                    if prior in MODALS:
                        value = 0.18
                    elif prior in FUTURE_OR_ADVICE or recent_modal:
                        value = -0.3
                    elif prior == 'to':
                        value = -0.45
                    elif prior in ADVERBS or prior.endswith('ly'):
                        value = -0.4
                    elif prior in ("'t", '’t', 'cannot'):
                        value = -0.35
            elif lower == 'by':
                value = -1.4
                if not raw.startswith(' ') or first.isupper():
                    value = -1.95
                elif prior in ('divided', 'divisible', 'multiplied'):
                    value = -0.45
                elif prior.endswith('ed'):
                    value = -1.10
        elif first.lower() == 'б':
            value = -1.8 if len(letters) == 1 else -2.1
            if lower.startswith(('был', 'быть', 'будет', 'более')):
                value = -0.9
        elif first.lower() == 'β':
            value = -1.2
        elif first == 'ب':
            value = -1.9 if len(letters) == 1 else -2.3
        elif first in 'ばびぶべぼバビブベボ':
            value = -1.8 if len(letters) <= 2 else -1.4
        elif b_sound(first):
            value = -1.6
        elif first in MANDARIN_B and first not in '不并並':
            value = -1.2 if len(letters) == 1 else -0.65
        elif any(b_sound(c) for c in letters):
            value = -0.75 if len(letters) <= 3 else -0.15
        # A doubled B is weaker than the first B in a word.
        if raw[:1].isalpha() and previous and b_sound(previous[-1]):
            if any(b_sound(c) for c in letters):
                value = 0.3
            else:
                value -= 0.55
        if raw.startswith('.B'):
            value = -0.9 if prior[-1:].isdigit() else -1.7
            if previous == raw:
                value = 0.2
    if raw.isdigit() and previous and b_sound(previous[-1]):
        value = -0.6
    if raw.startswith('_') and letters.lower() == 'b':
        value = -2.6
    if raw == '</tool_call>':
        value = 0.84
    if prior in MODALS | FUTURE_OR_ADVICE:
        recent_modal = 3
    else:
        recent_modal = max(0, recent_modal - 1)
    return (doc, s, recent_modal), value

programs.haiku:
"""Layer-0 MLP component 472: a 'b-word' detector.

Fires negative on tokens whose spelling starts with the letter b (Latin B/b or
Cyrillic б): strongly for ordinary b-words (bed, bay, board, black, build...),
weakly for the 'be' family (be, been, being, because, between...) and for
by/but, and mildly for words that merely contain a b. Everything else is ~0.
"""
READS = ()

BE_FAMILY = {"be", "been", "being", "become", "becomes", "became", "becoming",
             "begin", "began", "beginning", "before", "between", "because",
             "below", "beyond", "behind", "both"}
WEAK_B = {"by", "but", "back", "best", "better", "body", "book", "based"}
STRONG_B = {"bed", "bay", "bow", "bu", "ba", "bi", "bo", "br", "bl", "b", "bp"}


def step(carry, prefix, upstream):
    word = prefix.token_strings[-1].strip().lower()
    if word[:1] in ("b", "б"):
        if word in ("be", "been"):
            return carry, 0.0
        if word in BE_FAMILY:
            return carry, -0.6
        if word in WEAK_B:
            return carry, -1.2
        if word in STRONG_B:
            return carry, -2.5
        return carry, -2.0
    if "b" in word:
        return carry, -0.4
    return carry, 0.0

programs.luna:
"""Respond strongly to B-initial words and Mandarin b-syllables, weakly to other B tokens."""
READS = ()
MANDARIN_B = frozenset("吧把本杯")

def step(carry, prefix, upstream):
    token = prefix.token_strings[-1].casefold()
    word = token.lstrip().lstrip("-_")
    if word.startswith(("b", "б")):
        return None, -1.0
    if any(char in token for char in MANDARIN_B):
        return None, -1.0
    if "b" in token or "б" in token:
        return None, -0.4
    return None, 0.0

programs.sol:
"""Approximate a Q/QU spelling signal, especially unfinished QU syllables.

Longer words receive smaller estimates calibrated by familiar word families.
Related responses cover relative pronouns, Arabic qaf, equality and roots.
A little signal persists into a following word fragment or the connector
"of". There are small adjustments for bare Q at document starts and q ending
leq/geq commands. State resets between documents. Small background effects
and many multilingual associations are deliberately left unmodeled.
"""
import math

READS = ()

# Ordinary word families sharing QU. Values are activation estimates, not
# probabilities. The first matching family wins.
QU_FAMILIES = (
    (('question', 'request', 'requir', 'unique', 'frequen'), 0.8),
    (('technique', 'torque'), 0.0),
    (('inequal',), 0.35),
    (('equality',), 0.6),
    (('equal', 'equiv'), 1.25),
    (('equation',), 2.2),
    (('equity',), 3.5),
    (('quickly',), 1.55),
    (('quick', 'quiet', 'quite'), 2.8),
    (('quot',), 3.0),
    (('quantum', 'quantity', 'quantities'), 1.6),
    (('quant', 'quart'), 2.4),
    (('queen',), 2.1),
    (('squared',), 0.9),
    (('square',), 1.65),
    (('quadratic',), 1.4),
    (('subsequen', 'consequen'), 0.6),
    (('sequence',), 1.2),
    (('query',), 1.3),
    (('liquid', 'equip'), 1.8),
)


def spelling_value(raw):
    s = raw.strip().lower()
    if 'qu' in s:
        if s.endswith('qu'):
            if len(s) >= 5:
                return 2.0
            if s == 'equ' and not raw[:1].isspace():
                return 3.9
            if raw == ' qu':
                return 4.1
            return 5.0 if raw[:1].isspace() else 5.3
        if s == 'que':
            return 1.2 if raw == ' que' else 2.4
        if s == 'qui' and raw[:1].isspace():
            return 1.7 if raw == ' qui' else 3.3
        if s == 'equals':
            return 0.6
        if s == 'quad':
            return 2.8 if raw.strip() != s else 1.3
        if s.startswith('&quot'):
            return 0.2
        for family, value in QU_FAMILIES:
            if any(root in s for root in family):
                return value
        if 'quality' in s:
            return 1.3 if raw.strip() == s else 1.75
        # Final -ique and -que are often French spellings rather than an
        # unfinished QU syllable, and tend to be weaker.
        if s.endswith(('ique', 'iques', 'iquer')):
            return 1.65 if s == 'ique' else 1.2 if len(s) == 5 else 0.25
        if s.endswith('que') and len(s) >= 5:
            return 0.8
        tail = s.rsplit('qu', 1)[1]
        if any(c.isalpha() and not c.isascii() for c in tail):
            return 1.5
        n = sum(c.isalpha() for c in tail)
        return 1.1 + 3.8 * math.exp(-n / 2.3)
    if 'q' in s:
        if 'sqrt' in s:
            return 1.03
        letters = ''.join(c for c in s if c.isalpha())
        return 1.1 if letters == 'q' else 1.7 if letters == 'eq' else 1.65
    if 'ق' in s:
        stem = s.removeprefix('ال')
        return 4.1 if stem == 'ق' else 2.0 if len(stem) == 2 else 1.1
    if s in {'who', 'which', 'whose', 'whom'}:
        return 0.73
    if s.startswith('котор'):
        return 0.55
    if raw == ' che':
        return 0.65
    if '√' in s:
        return 1.08
    if '==' in s or s == '等':
        return 0.85
    return 0.0


def step(carry, prefix, upstream):
    raw = prefix.token_strings[-1]
    doc = prefix.document_ids[-1]
    fresh = carry is None or carry[0] != doc
    previous = '' if fresh else carry[1]
    value = spelling_value(raw)
    if fresh and raw in {'Q', 'q'}:
        value = -0.28 if raw == 'Q' else 0.0
    if raw == 'q' and previous in {'le', 'ge'}:
        value = 0.6  # The final letter of mathematical leq/geq commands.
    if raw == ' of' and 'q' in previous.lower():
        value = 0.3 * spelling_value(previous)
    # A letter token without leading whitespace can continue the Q word.
    if raw and raw[0].isalpha() and 'q' not in raw.lower():
        p = previous.strip().lower()
        if 'q' in p:
            if p == 'q':
                value += 0.8
            elif p.endswith('qu'):
                value += 1.0 if previous.strip() == p else 1.5
            else:
                value += 0.2
    return (doc, raw), float(value)

