"""Estimate the positive response to Q-marked tokens and relative pronouns."""
READS = ()

RELATIVE_PRONOUNS = {"which", "who", "whose", "whom", "которые"}


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1].strip().lower()
    if "q" in token:
        return None, 1.35
    if token in RELATIVE_PRONOUNS:
        return None, 0.70
    if token == "√":
        return None, 1.05
    return None, 0.0

programs.sol:
"""A signed, local collocation detector with a small word-shape background.

Negative: light-verb completions (take care, give rise/birth, make efforts,
pay attention), recipients of giving/providing, and some `for` constructions.
Positive: asking about questions, directional verb particles, transaction
quantities, and request/call compounds in code. A strong negative phrase can
continue onto its following `of` or `to`. Two preceding tokens and a phrase flag are kept;
document boundaries clear them. This does not explain the diverse weak lexical
responses outside these patterns.
"""

READS = ()
TAKE = {'take', 'takes', 'taking', 'taken', 'took'}
GIVE = {'give', 'gives', 'giving', 'given', 'gave'}
MAKE = {'make', 'makes', 'making', 'made'}
PAY = {'pay', 'pays', 'paying', 'paid'}
ASK = {'ask', 'asks', 'asking', 'asked'}
BUY = {'buy', 'buys', 'buying', 'bought'}
CALL = {'call', 'calls', 'calling', 'called'}
SUPPLY = GIVE | {'provide', 'provides', 'provided', 'providing',
                 'allow', 'allows', 'allowed', 'allowing',
                 'offer', 'offers', 'offered', 'offering'}
TRANSFER = TAKE | MAKE | PAY | BUY | CALL | ASK | SUPPLY | {
    'request', 'requested', 'send', 'sent', 'receive', 'received',
    'sell', 'sold', 'purchase', 'purchased', 'choose', 'chosen'}


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        carry = (doc, '', '', '')
    _, previous, earlier, phrase = carry
    raw = prefix.token_strings[-1]
    spelling = raw.strip()
    word = spelling.lower()
    value, current_phrase = 0.0, ''

    # Weak background from ASCII word length and mixed case.
    if word.isascii() and word.isalpha():
        value = 0.002 * (min(len(word), 12) - 3)
        if not (spelling.islower() or spelling.isupper() or spelling.istitle()):
            value = 0.045
    elif word.isnumeric():
        value = -0.0015

    if previous in TRANSFER:
        if word == 'for':
            value = -0.19
        elif word in {'from', 'in', 'by'}:
            value = 0.20
    if previous in GIVE and word in {'in', 'by', 'for'}:
        value = -0.03
    if previous in ASK and word == 'for':
        value = 0.01

    if word == 'care':
        value = -0.06
        if previous in TAKE or (earlier in TAKE and previous in
                                {'great', 'particular', 'special', 'good'}):
            value, current_phrase = -0.82, 'care'
    elif word in {'rise', 'birth'}:
        value = -0.08
        if previous in GIVE:
            value, current_phrase = -0.83, 'giving'
    elif word == 'of' and phrase == 'care':
        value = -0.58
    elif word == 'to' and phrase == 'giving':
        value = -0.42
    elif previous in MAKE and word in {'effort', 'efforts'}:
        value = -0.73
    elif previous in MAKE and word in {'sure', 'sense', 'use'}:
        value = -0.22
    elif previous in MAKE and raw == 'file':
        value = -0.25
    elif previous in PAY and word == 'attention':
        value = -0.53
    elif previous in SUPPLY and word in {'you', 'me', 'us'}:
        value = -0.30
    elif previous in ASK and word in {'about', 'who', 'if', 'whether'}:
        value = 0.58 if word in {'about', 'who'} else 0.45
    elif previous in ASK and word in {'what', 'how', 'when', 'where', 'which'}:
        value = 0.30
    elif previous in TAKE and word in {'over', 'up', 'into', 'from', 'part'}:
        value = 0.50 if word == 'over' else 0.34 if word == 'up' else 0.23
    elif previous in PAY and word in {'through', 'per', '-per', 'stub', 'tm'}:
        value = 0.78 if word in {'through', 'stub', 'tm'} else 0.60
    elif previous in PAY and word in {'in', 'by', 'back'}:
        value = 0.36
    elif previous in BUY and word in {'through', 'from', 'over', 'back'}:
        value = 0.60
    elif previous in CALL and word == 'stack':
        value = 0.73
    elif previous in CALL and word == 'from':
        value = 0.41
    elif word == 'volume':
        value = 0.09
        if previous in {'trade', 'trading', 'call', 'calls'}:
            value = 1.0 if previous in {'trade', 'trading'} else 0.82
    elif previous == 'request' and word.lstrip('_.') in {
            'queue', 'context', 'body', 'header', 'headers', 'dispatcher'}:
        value = 0.64
    # Chinese commercial amount/volume and buyer/seller suffixes.
    elif word == '额' and previous in {'贸易', '交易', '还款'}:
        value = 0.80
    elif word == '量' and previous in {'销售', '交易', '供应', '货运'}:
        value = 0.80
    elif word == '方' and previous in {'买', '卖'}:
        value = 0.72
    return (doc, word, previous, current_phrase), value

programs.haiku:
"""Light-verb idiom detector (layers.0.mlp.down_proj:474).

Mainly a negative response to the noun that completes a light-verb idiom:
"care" in "take care (of)", "rise" in "give rise (to)", "birth" in "give birth (to)".
The verb must come just before the noun, in the same document. These nouns get about
-0.85; the same nouns elsewhere stay near 0. Weaker effects: "sure" after "make" (-0.2),
and "volume" after "the/to" (+0.1). Everything else is 0.
"""

READS = ()

TAKE_VERBS = {"take", "takes", "took", "taken", "taking"}
GIVE_VERBS = {"give", "gives", "gave", "given", "giving"}
IDIOM_NOUNS = {"care": TAKE_VERBS, "rise": GIVE_VERBS, "birth": GIVE_VERBS}
IDIOM_VALUE = -0.85
WEAK = {("sure", "make"): -0.2, ("volume", "the"): 0.1, ("volume", "to"): 0.1}


def step(carry, prefix, upstream):
    t = prefix.position
    word = prefix.token_strings[t].strip().lower()
    if t == 0 or prefix.document_ids[t - 1] != prefix.document_ids[t]:
        return None, 0.0
    previous = prefix.token_strings[t - 1].strip().lower()
    if previous in IDIOM_NOUNS.get(word, ()):
        return None, IDIOM_VALUE
    return None, WEAK.get((word, previous), 0.0)


def main():
    """Print the predicted value for a few short phrases."""
    for phrase in ["they will take care", "this gave rise", "she gave birth", "health care"]:
        words = phrase.split()
        previous, noun = words[-2], words[-1]
        value = IDIOM_VALUE if previous in IDIOM_NOUNS.get(noun, ()) else 0.0
        print(f"{phrase!r}: noun {noun!r} -> {value}")


if __name__ == "__main__":
    main()

