    if word == "of" and previous == "care":
        return None, -0.55
    if word == "rise" and previous in {"give", "gives", "gave", "giving"}:
        return None, -0.80
    if word == "to" and previous == "rise":
        return None, -0.42
    if word == "birth" and previous in {"give", "gives", "gave", "giving"}:
