programs.sol:
"""Approximate a negative formatting-separator and 'of'-phrase response.
The strongest whitespace responses in training were isolated tabs and
nonbreaking spaces. Continuing a whitespace run attenuates them; combined
whitespace tokens have separate estimates. A small phrase inventory covers
strong 'of' responses after manner, location, and time words. Constants are
fitted activation estimates; other lexical variation is left at zero.
"""
import math

READS = ()


def of_response(previous):
    """A few common locative, manner, and time expressions ending in 'of'."""
    word = previous.strip().lower()
    if word == 'way':
        return -1.29
    if word == 'ways':
        return -1.14
    if word == 'country':
        return -0.91
    if word in {'out', 'ahead', 'year', 'years'}:
        return -0.69
    if word in {'method', 'month'}:
        return -0.54
    if word in {'north', 'south', 'east', 'west', 'direction'}:
        return -0.46
    if word in {'day', 'days', 'week', 'weeks', 'months', 'hour', 'hours'}:
        return -0.40
    return 0.0


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    doc = prefix.document_ids[-1]
    # Only the immediately previous token in the same document is retained.
    previous = carry[1] if carry is not None and carry[0] == doc else ''
    value = 0.0
    if token == '\t':
        if not previous:
            value = -0.73
        elif previous.strip('\t ') == '':
            value = -0.68 if '\t' in previous else -0.84
        elif previous.strip().isdigit():
            value = -1.08
        else:
            value = -1.16 if '\n' in previous else -1.25
    elif token and not token.strip('\t'):
        value = -0.87 / math.sqrt(len(token))
    elif token == '\xa0':
        if previous == ' ':
            value = -0.42
        elif previous and not previous.strip('\xa0 '):
            value = -0.64
        elif previous.strip().isdigit():
            value = -1.06
        elif previous and previous[-1].isalpha():
            value = -1.20
        else:
            value = -1.14
    elif token and not token.strip('\xa0'):
        value = 0.15 if len(token) >= 4 else 0.02
    elif token in {'nbsp', '&nbsp'}:
        value = -1.10 if '&' in token or previous.endswith('&') else -0.56
    elif token == ' \xa0':
        value = -0.13
    elif token and not token.strip('\t \r\n') and '\t' in token:
        if '\n' in token:
            value = -0.16 if token.count('\n') == 1 else -0.04
        elif token.startswith(' '):
            value = -0.41
        elif ' ' in token.rstrip(' '):
            value = -0.11
        else:
            spaces = token.count(' ')
            value = -0.12 if spaces <= 2 else -0.025 if spaces <= 4 else 0.08
    elif token == ' of':
        value = of_response(previous)
    return (doc, token), value

programs.haiku:
"""Draft 5: layout whitespace (a lone tab or non-breaking space, strongly negative;
a double tab, less so), plus ' of' in a few fixed phrases ('out of', 'way of',
'years of', 'country of'), moderately negative."""

READS = ()

LEVELS = {"\t": -1.1, "\xa0": -0.9, "\t\t": -0.6}
OF_AFTER = {"out", "way", "years", "country"}


def step(carry, prefix, upstream):
    tok = prefix.token_strings[-1]
    if tok in LEVELS:
        return carry, LEVELS[tok]
    if tok == " of" and len(prefix.token_strings) > 1:
        if prefix.token_strings[-2].strip() in OF_AFTER:
            return carry, -0.8
    return carry, 0.0

