programs.sol:
"""Approximate a 'text begins here' response.

Positive cues are quotes introducing output messages, prompts, descriptions,
labels, tests, and JSON strings; TeX text and documentation tags also count.
Imports, selector strings, and equality comparisons are weaker or negative.
This uses familiar word classes, not a token-id lookup. A bounded text suffix
supplies the naming word, and is cleared at each new document.
"""
import re

READS = ()
OUTPUT = set('print printf println writeline writeln puts echo log info debug '
             'warn warning fatal perror errorf logf fatalf warnf infof sprintf '
             'kprintf printerror print_error logerror alert'.split())
PROMPTS = set('input raw_input prompt question'.split())
DESCRIPTIONS = set('description help caption title xlabel ylabel zlabel '
                  'ggtitle placeholder legend'.split())
LABELS = set('text label settext textcontent innertext jlabel textview header '
             'jframe jbutton argumentparser'.split())
TESTS = set('it test describe context fail'.split())
MESSAGES = set('message msg mensaje instruction thought output snippet'.split())
TECHNICAL = set('require import load client getaxis addeventlistener '
                'createelement queryselector queryselectorall getelementbyid '
                'findall dllimport requestparam pathvariable'.split())
SPEECH = set('says said say saying writes wrote states stated replied asks '
             'asked called named titled entitled means meaning phrase word '
             'words sentence slogan term statement question example'.split())


def purpose(word):
    word = word.lower()
    if word in DESCRIPTIONS or word.endswith(('title', 'caption', 'description')):
        return 'description'
    for name, words in [('label', LABELS), ('prompt', PROMPTS), ('test', TESTS),
                        ('output', OUTPUT), ('message', MESSAGES),
                        ('technical', TECHNICAL)]:
        if word in words:
            return name
    return 'error' if word.endswith(('error', 'exception')) else word


def response(token, before):
    words = re.findall(r'[A-Za-z_][A-Za-z_0-9]*',
                       before.replace('\\n', '\n').replace('\\t', '\t'))
    word = words[-1] if words else ''
    role, s = purpose(word), token.strip()
    if s in {'{"', "{'"}:
        return 1.25 if token.startswith(' ') else 0.82
    if s in {'["', "['"}:
        return 0.3
    if s in {'","', "','", '":"'}:
        return 1.3 if ':' in s else 0.6
    if s.count('"') >= 2 or s.count("'") >= 2:
        return 0.08                     # Empty/closed string, not text to come.
    if re.match(r'["\'](?:[),;]|\s*[),;])', s):
        return 0.0
    if re.match(r'\((?:\{)?(?:\\)?["\'`]', s):
        value = {'output': 2.85 if "'" in s else 2.4, 'prompt': 3.8,
                 'test': 3.0, 'description': 3.8, 'label': 2.6, 'error': 2.7,
                 'technical': -0.6, 'message': 2.2}.get(role, 0.3)
        value *= 0.3 if s.startswith('(\\') else 0.75 if '\\' in s else 1.0
        return value * (0.35 if s.endswith(('%', '#', '$', '<', '@')) else 1.0)
    if re.match(r'!\(["\'`]', s):
        return 2.7                     # Rust printing/formatting macros.
    if s == '(f':
        return 1.65 if role in {'output', 'error'} else 0.3
    if s.startswith(('"', "'", '\\"', "\\'")):
        if re.search(r'(?:^|[\s(:=])f$', before):
            return 2.0                 # Formatted string opener.
    if s.startswith(('="', "='", '=\\"')) or (
            token[:1].isspace() and s.startswith(('"', "'"))):
        if re.search(r'[!=]=+\s*$', before):
            return -0.45
        if re.search(r'(?:#include|\bfrom|\bimport)\s*$', before):
            return -0.35
        if re.search(r'(?:[:=]|=>)\s*$', before) or s.startswith('='):
            if word.lower() in {'xmlns', 'ui'}:
                return -1.5
            if before.endswith('Title:') or re.search(r'[+]=\s*$', before):
                return 0.9
            return {'description': 3.6, 'label': 2.2, 'message': 1.5,
                    'name': 1.55, 'command': 0.85, 'type': 0.0,
                    'content': 0.95, 'value': 0.65, 'id': 0.45,
                    'style': 0.5}.get(role, 0.35)
        if word == 'COMMENT':
            return 4.1                 # SQL column documentation.
        if word.lower() in SPEECH:
            return 0.75
        if role == 'output' and word.lower() not in {'log', 'debug', 'info', 'warn'}:
            return 1.5
        if re.search(r'<<\s*$', before):
            return 1.4 if '"' in s else 0.4
        if re.search(r'["\'],\s*$', before):
            return 0.35
        return 0.85 if word.lower() == 'return' else 0.0
    if token == '{':
        match = re.search(r'\\([A-Za-z]+)$', before)
        command = match.group(1) if match else ''
        if command in {'caption', 'section', 'subsection', 'subsubsection'}:
            return 3.4
        if command in {'textbf', 'textit', 'footnote'}:
            return 1.9
        if command.startswith('text') or command == 'operatorname':
            return 1.2
        if command in {'mathrm', 'mathbf', 'mbox', 'boxed', 'label', 'ref', 'cite',
                       'citep', 'bm'}:
            return 0.7
        return 0.16 if command else 0.05
    if token in {'brief', 'desc', 'description', 'item'}:
        return 2.2 if before.endswith(('\\', '@')) else 0.0
    if token in {'summary', 'details', 'label', 'title'} and before.endswith('<'):
        return 1.5
    if token == 'bf' and before.endswith('\\text'):
        return 1.9
    if token == 'text' and before.endswith('\\'):
        return 0.5
    if token == '{*' and before.endswith('\\text'):
        return 2.8
    if s in {'>', '">', '}>'}:
        text_tag = re.search(r'<(?:title|label|summary|p|b|i|h[1-6])'
                             r'(?:\s[^<>]*)?$', before)
        return 0.9 if text_tag else 0.1
    if s in {'**', '***'}:
        return 0.25
    if s in {'「', '『', '“', '‘', '：“'}:
        return 0.65 if '：' in s else 0.1
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    before = carry[1] if carry is not None and carry[0] == doc else ''
    token = prefix.token_strings[-1]
    return (doc, (before + token)[-160:]), float(response(token, before))

programs.haiku:
"""Opening quote or bracket of a string literal, scored by whether the string is about to be
shown to a person.

Fires on the token that opens a string or a brace in code or markup: ' "', " '", '("', "('",
'{"', '{', '="', '!("' and the like. Its size depends on the words just before it:
- a call that displays text (print, println, printf, log, alert, echo, cout <<, f-string,
  it("...") test titles, setTitle, label, title, description, message): large, about 2.5;
- a JSON key whose value is prose ("description", "message", "name", "text"): its strength
  for that key;
- code-level syntax (require, ===, addEventListener, createElement, #include): negative;
- a bare line start, return, or => : moderate; anything else: small.
Every other token predicts 0. The program is a word list, not a model of the network."""

READS = ()

# Words after which a string literal is displayed to a person.
SHOWN_BEFORE = {
    "print", "println", "printf", "Printf", "Println", "Sprintf", "f", "format", "log", "alert",
    "echo", "cout", "<<", "perror", "warn", "trace", "Infof", "puts", "say", "input", "COMMENT",
    "setTitle", "title", "it", "text", "label", "caption", "footnote", "description", "message",
    "says", "Error", "Header",
}
# JSON keys whose string value is prose, with how strongly the value opens.
PROSE_KEYS = {"description": 4.5, "message": 2.2, "name": 1.6, "arguments": 1.3, "text": 1.3,
              "command": 0.9}
# Code-level words before a quote: the string is an identifier, path or config value.
CODE_BEFORE = {
    "require", "createElement", "addEventListener", "===", "!==", "==", "#include", "table",
    "Column", "-type", "align", "from", "insert", "getItem", "AND", "|", "on",
}
# Words before a quote that is closing or punctuation, not opening a literal.
PLAIN_BEFORE = {",", '",', ".", " and", " the", " a", " ="}
QUOTES = ('"', "'")
# Tokens that open a string or brace, with the text that may precede the quote.
OPEN_PREFIX = (" ", " (", "(", "!(", "{", " {", "=", "(f", "(\\", " ('", " (\\", "<<", " <<", "[")


def _word(s):
    return s.strip(" .\n\t(!{=")


def _opens_string(tok):
    if tok in ("{", " {"):
        return True
