"""Component layers.0.mlp.down_proj:478: an "at least" detector.

The component is strongly negative on the word "least" when it comes right after
"at" ("at least one", "At least", "for at least 2 weeks"). That is nearly its whole
job. It is weaker on a few neighbouring cases that share the "lower limit / qualifier"
sense: "the least", "at most", the foreign ways of saying "at least" (Chinese 至少,
Italian "al meno", French "au moins" / "du moins"), and the hedges "hopefully",
"preferably", "ideally", "certainly". Everything else is predicted as 0.
"""

READS = ()

AT_LEAST = -4.1        # "at least"
LEAST_ELSE = -0.7      # "least" in other frames: "the least", "last but not least"
AT_MOST = -1.0         # "at most"
HEDGES = -0.9          # "hopefully", "preferably", "ideally", "certainly"
CHINESE_AT_LEAST = -2.7  # 至少
ITALIAN_AL_MENO = -2.0   # "al meno"
FRENCH_MOINS = -0.9      # "au moins", "du moins"

HEDGE_WORDS = {"hopefully", "preferably", "ideally", "certainly"}
FRENCH_BEFORE_MOINS = {"au", "du", "à", "et"}


def _word(s):
    return s.strip().lower()


def step(carry, prefix, upstream):
    tok = _word(prefix.token_strings[-1])
    same_doc = len(prefix) > 1 and prefix.document_ids[-2] == prefix.document_ids[-1]
    prev = _word(prefix.token_strings[-2]) if same_doc else ""
    if tok == "least":
        return carry, (AT_LEAST if prev == "at" else LEAST_ELSE)
    if tok == "most" and prev == "at":
        return carry, AT_MOST
    if tok in HEDGE_WORDS:
        return carry, HEDGES
    if tok == "至少":
        return carry, CHINESE_AT_LEAST
    if tok == "meno" and prev == "al":
        return carry, ITALIAN_AL_MENO
    if tok == "moins" and prev in FRENCH_BEFORE_MOINS:
        return carry, FRENCH_MOINS
    return carry, 0.0

