SPACED_PRONOUNS = {
    'они': 3.75, 'Они': 3.75, 'их': 3.65, 'них': 3.85, 'им': 0.92,
    'ils': 3.36, 'Ils': 3.36, 'elles': 1.66, 'leur': 3.20,
    'leurs': 3.20, 'les': 0.86,
    'sie': 2.06, 'Sie': 0.82, 'ihnen': 3.05, 'ihre': 1.70,
    'ihrer': 1.73, 'ihrem': 1.90, 'ihren': 0.93, 'deren': 1.67,
    'ihr': 0.53, 'ihn': 0.75, 'ihm': 0.73,
    'ellos': 3.76, 'eles': 1.64, 'loro': 3.89, 'mereka': 3.33,
    'họ': 3.14, 'لهم': 3.62,
}
UNSPACED_REFERENCE = {
    '他们': 4.75, '他們': 5.53, '他们的': 4.24, '它们': 2.83,
    '这些': 0.85, '那些': 0.27, '其他': 1.05, '等': 1.05,
    'هم': 2.37, 'ها': 0.98, '들': 0.80,
}


