        value = PLURAL[lower]
        if word != lower:
            value *= 0.92
        if not spaced:
            value *= 0.93 if lower != 'them' else 0.73
        if start:
            value *= 0.56 if lower == 'they' else 0.65
        return None, float(value)
    if lower in REFERENCE:
        value = REFERENCE[lower]
        if lower == 'it':
            if word == 'It':
                value = 1.20
            elif word == 'IT':
                value = 0.65 if spaced else 0.10
            if not spaced and word == 'it':
                value = 0.21  # Often a suffix inside a larger word.
        elif word != lower:
            value += {'these': 0.13, 'other': 0.25, 'there': -0.10,
                      'another': -0.10}.get(lower, 0.0)
        if lower == 'other' and not start:
            if prefix.token_strings[-2].strip().lower() == 'each':
                value = 0.18
        return None, float(value)
    if lower in {'his', 'her', 'its'}:
        return None, -0.15
    if spaced and word in SPACED_PRONOUNS:
        return None, float(SPACED_PRONOUNS[word])
    if word in UNSPACED_REFERENCE:
        return None, float(UNSPACED_REFERENCE[word])
