programs.sol:
"""A spelling detector for the consonant pair pr (also Cyrillic пр).

The largest predictions are for bare pr / пр fragments, with adjustments
for case, script and adjoining punctuation. Following letters change the
response: pra- and pri- are generally stronger than pro-, and longer tails
usually weaken it. A bare fragment also has a small one-token after-effect
on an alphabetic continuation. State resets at document boundaries.

This models the main spelling pattern, not the varying responses to whole
words or translations. There is deliberately no word-activation table.
"""
import unicodedata

READS = ()
CYRILLIC = str.maketrans('приеоа', 'prieoa')


def spelling(token):
    text = token.lower().translate(CYRILLIC)
    text = unicodedata.normalize('NFD', text)
    return ''.join(c for c in text if c.isalpha())


def strength(token):
    word = spelling(token)
    at = word.find('pr')
    if at < 0:
        # Related fr fragments are a much smaller response.
        return 0.55 if word == 'fr' else 0.0
    tail = word[at + 2:]
    cyrillic = 'п' in token.lower()
    if not tail:
        if at:
            if word.startswith('ex'):
                return 0.65
            if at == 1:
                return 2.3 if word[0] in 'aeiou' else 3.0
            return 2.3 if at == 2 else 1.05
        if 'ř' in token.lower():
            return 1.75
        letters = ''.join(c for c in token if c.isalpha())
        title = letters in ('Pr', 'Пр')
        if cyrillic:
            return 4.2 if title else 3.6
        value = 5.7 if title else 4.65
        if '.' in token:
            value += 2.5
        elif '-' in token or '/' in token:
            value += 1.3
        return value
    if at:
        if at == 1 and len(word) <= 8 and tail[0] in 'aiu':
            return 1.1
        return 0.1 + 1.0 / (len(tail) + 1)
    n = len(tail) + 1
    if tail[0] == 'a':
        return 0.4 if cyrillic else 2.25 - 1.55 / n
    if tail[0] == 'e':
        return 2.2 / n
    if tail[0] == 'i':
        return 0.15 + 4.0 / n
    if tail[0] == 'o':
        return 0.03 + 0.3 / n
    if tail[0] == 'u':
        return 3.2
    return 1.15 + 3.1 / n


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    doc = prefix.document_ids[-1]
    value = strength(token)
    if carry is not None and carry[0] == doc:
        if carry[1] and token[:1].isalpha():
            value += 0.6
    bare = spelling(token) == 'pr'
    return (doc, bare), float(value)

