"""Component layers.0.mlp.down_proj:483 -- a "word starts with pr-" detector.

It fires on the current token when that token begins with the letters p-r (or the
Cyrillic п-р) but not p-r-o (or п-р-о):
  * the bare fragment "pr" / "Pr" / "PR" / "пр" (also after a space or "_") is strongest;
  * short pr-openings ("pra", "pre", "pri", "prim", "print", "prize", "при") are moderate;
  * longer pr-words ("prime", "pricing", "pruning", "practice") are weaker;
  * "pro..." / "про..." pieces (product, program, provide, process) stay silent.
Everything else predicts 0. The program is stateless: it reads only the newest token.
"""

READS = ()

BARE = ("pr", "пр")          # the bare two-letter opening, any case
NO_FIRE_PREFIXES = ("pro", "про")  # "pro" openings do not fire


def predict(token):
    word = token.strip().lower().lstrip("_#")
    if word in BARE:
        return 4.5
    if not word.startswith(BARE):
        return 0.0
    if word.startswith(NO_FIRE_PREFIXES):
        return 0.0
    if len(word) <= 4:
        return 1.8
    return 0.8


def step(carry, prefix, upstream):
    return carry, float(predict(prefix.token_strings[-1]))

programs.sol:
"""Recognize compact list and quoted-field boundaries within the current token.

The largest responses are to a quote--separator--quote bridge. Smaller ones
mark commas/colons joined to identifiers, or a space before a comma. JSON's
name key and class/className or -type attributes get small contextual responses.
The preceding token is remembered only within the same document. Ordinary
text and standalone commas/colons are otherwise left near zero.
"""
READS = ()
QUOTES = "\"'`"
CLOSERS = frozenset(")]}'\"`")
OPENERS = frozenset("([{'\"`")
LITERALS = frozenset(('None', 'null', 'true', 'false', 'True', 'False'))
FUNCTION_WORDS = frozenset(('a', 'an', 'and', 'or', 'the', 'of', 'in', 'to'))
# What separates quoted fields: punctuation, nesting, and an associative arrow.
BRIDGES = (
    (',', 2.9), (':', 3.2), ('.', 2.7), ('+', 2.5), ('=>', 2.1),
    ('][', 2.1), (':{', 2.4), (',[', 2.4), (',{', 2.4),
    (':[', 2.7), (':[{', 2.3),
    ('],', 1.8), ('},', 1.8), ('},{', 1.7),
)


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    doc = prefix.document_ids[-1]
    previous = carry[1] if carry is not None and carry[0] == doc else ''
    return (doc, token), float(response(token, previous))


def response(token, previous):
    text = token.replace('\\', '').strip()
    spaced = token.startswith(' ')
    # Separator literals passed to a function are weaker than field bridges.
    literal = text.lstrip('(').rstrip(');')
    if text.startswith('(') and len(literal) == 3:
        if literal[0] == literal[-1] and literal[0] in QUOTES:
            if literal[1] in ',./':
                return {',': 1.4, '.': 0.5, '/': 0.8}[literal[1]]
    # Address-of arguments, range boundaries, and template fields.
    if text in ('",&', '):(', '}:${'):
        return {'",&': 1.55, '):(': 0.95, '}:${': 0.93}[text]
    for quote in QUOTES:
        if text.count(quote) < 2:
            continue
        for separator, strength in BRIDGES:
            bridge = quote + separator + quote
            if bridge not in text:
                continue
            if text != bridge:
                strength *= 0.8
            elif spaced:
                strength = {',': 2.5, ':': 1.9, '.': 0.85, '+': 1.65}.get(
                    separator, strength * 0.7)
            if '\\' in token:
                strength *= 0.85
            return strength
        if len(text) == 3 and text[0] == text[-1] == quote:
            if text[1] in '/_%=;#-':
                return 1.0 if spaced else 2.0
    if text.count(',') == 1:
        left, right = text.split(',')
        opening = right.rstrip('+-')  # A signed first value can follow a bracket.
        if left and opening and set(left) <= CLOSERS and set(opening) <= OPENERS:
            return 0.9 if '(' in right or right in QUOTES else 1.3
    if text in ('><', '"/><', '"><'):
        return 0.31
    if text in ('」「', '】【'):
        return 1.7 if text == '」「' else 1.24
    if token in (' ,', ' :'):
        return 0.41 if token[-1] == ',' else 0.10
    if token == '":':
        return 0.107 if previous == 'name' else 0.01
    if token == '="':
        return 0.25 if previous in (' class', ' className', '-type') else 0.12
    if len(token) > 1 and token[0] in ',:;':
        separator, tail = token[0], token[1:]
        if tail.startswith('\\') and tail[-1:] in QUOTES:
            tail = tail.replace('\\', '')
        if tail.isalpha():
            if separator == ',':
                if tail in LITERALS or tail.lower() in FUNCTION_WORDS:
                    return 0.70
                return 0.75 if len(tail) == 1 else 0.95
            if separator == ':':
                return 0.67 if len(tail) == 1 else 0.73
            return 0.40
        if len(tail) == 1 and tail.isascii() and not tail.isspace():
            if tail == '\\':
                return {',': 0.24, ':': 0.14, ';': 0.08}[separator]
            if tail in QUOTES:
                return {',': 0.17, ':': 0.50, ';': 0.08}[separator]
            if tail in '[]{}()':
                return {',': 0.33, ':': 0.46, ';': 0.13}[separator]
            if not tail.isdigit() and tail != separator:
                return {',': 0.55, ':': 0.58, ';': 0.13}[separator]
    return 0.0

