import re

READS = ()
COUNTS = {
    'one': 0.04, 'two': -0.92, 'three': -2.02, 'four': -2.27,
    'five': -2.0, 'six': -2.15, 'seven': -2.25, 'eight': -1.85,
    'nine': -1.85, 'ten': -1.72,
