    'first': 0.0, 'second': -0.03, 'third': -0.62, 'fourth': -0.59,
    'fifth': -0.74, 'sixth': -0.62, 'seventh': -0.9,
    'eighth': -0.15, 'ninth': -0.52, 'tenth': -0.3,
}
