    'twice': -0.42, 'double': -0.16, 'triple': -0.9, 'trio': -0.9,
    'cubic': -0.48, 'quadratic': -0.26, 'multi': -0.32,
    'decade': -1.0, 'century': 0.48, 'cent': 0.42,
    'hundreds': 0.35, 'thousands': 0.45,
}
CONNECTORS = {'-', '–', ',', 'and', 'or', 'to', '-to'}
HAN_DIGITS = '一二三四五六七八九十百千万两兩'
HAN_BEGIN = re.compile('^([' + HAN_DIGITS + ']+)(.*)$')
HAN_END = re.compile('[' + HAN_DIGITS + ']+$')
