HAN_COUNTS = dict(zip('一二两兩三四五六七八九十',
                     (0.1, -0.2, -0.6, -0.6, -1.15, -0.95,
                      -0.95, -1.0, -0.95, -0.5, -1.3, -1.75)))


def chinese_count(token, previous, start):
    match = HAN_BEGIN.fullmatch(token)
    if not match:
        return 0.0
    number, suffix = match.groups()
    time_unit = suffix.startswith(('年', '天', '月', '周', '分', '季', '个月', '個月'))
    if suffix and not time_unit and suffix[0] not in CLASSIFIERS:
        return 0.0
