        value = 1.6 if number == '一' else 3.2 if number == '五' else 2.8
        if number == '十三':
            value = 2.1
        if suffix.startswith('年'):
            value = 0.8 if number.startswith('十') else 2.0
        if number in ('万', '千'):
            value = 1.0 if number == '万' else 2.4
