        return 0.6 if len(number) == 1 else 0.1
    if previous.isdecimal():
        return 0.3 if number == '万' else 0.8 if number == '千' else 0.0
    if number.startswith('一'):
        return 0.1 if not suffix else 0.0
    if number in ('百', '千', '万'):
        return -1.1 if suffix.startswith(('家', '年')) else -0.3 if not suffix else 0.0
    if token == '十分':
        return -0.4  # The common adverb "very".
    if time_unit:
        return -0.6 if number in '二两兩' else -1.8 if number == '十' else -1.5
    if suffix:
        return -1.15 if number in '二两兩' else -3.2 if number == '十' else -2.5
    return HAN_COUNTS.get(number, -1.4 if number.startswith('十') else -0.55)


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    start = carry is None or carry[0] != doc
    previous, number, gap, tail = ('', '', 0, '') if start else carry[1:]
    raw = prefix.token_strings[-1]
