            value = 0.65 if word == 'one' else 2.2 if word == 'five' else 1.6
        elif previous in ORDINALS:
            value = 0.37 if word == 'one' else 0.12 if word == 'two' else value * 0.3
        elif number:
            value = 0.65 if gap == 0 else value * 0.35
        elif previous in ('the', 'these', 'this'):
            value -= 0.35
        elif previous in ('only', 'last', 'next', 'every', 'exactly', 'between'):
            value += 0.6
        if not start and token.isupper():
            value *= 0.55
        elif not start and token[:1].isupper() and word != 'two' and value < 0:
            value += 0.2
        if not start and raw == token and token.islower() and token[0] != '-':
            value *= 0.18 if word == 'ten' else 0.75
    elif word in MAGNITUDES:
        counted = number or previous in ('few', 'several', 'many')
        if counted:
            value = MAGNITUDES[word]
        else:
            value = 0.15 if previous in ('a', 'an') else 0.6
        if not counted and word not in ('hundred', 'thousand'):
            value = 0.05
    elif word in ORDINALS:
        value = ORDINALS[word]
        if start:
            value = 0.25 if word == 'first' else 1.0 if word == 'second' else 1.4
        elif number:
            value = 0.45 if word == 'first' else 0.8 if word == 'second' else 1.0
    elif word == 'half':
        value = 0.8 if previous in ORDINALS else 0.0
    else:
        value = GROUPS.get(word, chinese_count(token, previous, start))
    # Reassemble split preceding words, so "th" + "irty" counts as thirty.
    if not start and raw == token and token.isascii() and token.isalpha() and tail:
        tail = (tail + word)[-32:]
    else:
        ending = re.search(r'[a-z]+$', word)
        tail = ending.group() if ending else ''
    complete = word if word in COUNTS or word in MAGNITUDES else tail
    if complete in COUNTS or complete in MAGNITUDES:
        number, gap = complete, 0
    elif token in CONNECTORS and number and gap < 2:
        gap += 1
    else:
        number, gap = '', 0
    return (doc, tail or word, number, gap, tail), float(value)

