"""Infinitive "to", passive "by" and "based on": a word-triggered detector in layer 0.

This component is silent almost everywhere. It responds to three kinds of word:

* "to" that opens an infinitive ("to" plus a bare verb), after a word that takes one.
  How strongly depends on that word:
  - verbs of starting, continuing, trying and failing ("began to", "continued to",
    "attempted to", "failed to", "tried to"): about 4.5;
  - verbs and adjectives of wanting, ability, need and intention ("want to",
    "able to", "needed to", "decided to", "willing to", "hope to"): about 2.7;
  - "to" after an object pronoun ("allows you to", "asked him to"): about 1;
  - adjectives of ease and use ("easy to", "difficult to", "used to"): about 1.3;
  - "due to": about 0.8.
  Prepositional "to" ("according to", "equal to", "related to", "to the") is about 0.2,
  and "how to" / "way to" is slightly negative.
* "by", the agent of a passive or "divided by": about 0.8 everywhere.
* "on" after "based", "depend(s/ing)", "rely" or "focus": about 0.7.

Every other token predicts 0. A word also matches its regular -s, -ed and -ing forms,
so "wanting" counts as "want".
"""

READS = ()

START_TRY = {
    "begin", "began", "begun", "start", "continue", "attempt", "try", "tried", "fail",
    "refuse", "cease", "seek", "sought", "strive", "endeavour", "manage",
}
WANT_ABILITY = {
    "want", "need", "able", "unable", "ability", "inability", "capacity", "willing",
    "desire", "wish", "hope", "plan", "intend", "expect", "prefer", "eager", "ready",
    "decide", "choose", "chose", "chosen", "aim", "prepare", "designed", "required",
    "forced", "obliged", "allowed", "asked", "seem", "appear", "likely", "tend",
    "tendency", "opportunity", "effort", "efforts", "decision", "struggle",
}
EASE_USE = {
    "easy", "easier", "difficult", "hard", "possible", "impossible", "enough", "like",
    "used", "supposed", "necessary",
}
OBJECT_PRONOUN = {"you", "him", "her", "them", "me", "us", "it"}
MANNER = {"how", "way", "ways", "what"}
DEPEND_ON = {"based", "base", "depend", "rely", "focus", "dependent"}


def stems(word):
    """The word and its regular -s, -ed and -ing stems."""
    return {word, word[:-1], word[:-2], word[:-3], word[:-3] + "e"}


def step(carry, prefix, upstream):
    word = prefix.token_strings[-1].strip().lower()
    same_doc = len(prefix) > 1 and prefix.document_ids[-2] == prefix.document_ids[-1]
    prev = prefix.token_strings[-2].strip().lower() if same_doc else ""
    forms = stems(prev)
    if word == "by":
        return carry, 0.8
    if word == "on":
        return carry, 0.7 if forms & DEPEND_ON else 0.0
    if word != "to":
        return carry, 0.0
    if prev == "due":
        return carry, 0.8
    if forms & START_TRY:
        return carry, 4.5
    if forms & WANT_ABILITY:
        return carry, 2.7
    if prev in OBJECT_PRONOUN:
        return carry, 1.0
    if forms & EASE_USE:
        return carry, 1.3
    if prev in MANNER:
        return carry, -0.4
    return carry, 0.2

