programs.sol:
"""Predict the dominant horizontal-spacing response of this component.

Tabs and multi-space tokens between text items are positive; ordinary word
spaces and newline tokens are near zero. Real newlines suppress the response
of following indentation. Gap width, mixed tabs/spaces, and preceding diff or
comment markers adjust the magnitude. Tab-prefixed words have a separate small
response. Nonbreaking-space runs are weakly positive.

A secondary spelling rule handles alphabetic continuations of g/г-ending
tokens: another g is positive, short front-vowel continuations negative.
These character-level rules approximate the response, not its lexical details.
Only the previous token is carried, and documents reset that state.
"""
READS = ()


def space_gap(width):
    # A broad peak for medium-sized gaps, declining for very long padding.
    return max(-0.2, 0.76 + 0.04 * min(width, 12)
               - 0.022 * max(width - 14, 0))


def spelling_response(previous, text):
    """A secondary orthographic response in g-ending word fragments."""
    previous = previous.casefold()
    fragment = text.casefold()
    if not previous.endswith(("g", "г")) or not fragment.isalpha():
        return 0.0
    strength = 1.0 if len(previous.strip()) <= 2 else 0.65
    first = fragment[0]
    back_vowel = first in "aouаоу"
    if "g" in fragment or "г" in fragment:
        response = 0.85 * min(1.0, 3.0 / len(fragment)) if back_vowel else 0.25
    elif first in "eiеёиі":
        response = -0.5 * max(0.0, (5 - len(fragment)) / 4)
    else:
        response = 0.08 if back_vowel and len(fragment) > 1 else 0.0
    return response * strength


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    start = carry is None or carry[0] != doc
    previous = "" if start else carry[1]
    text = prefix.token_strings[-1]
    value = spelling_response(previous, text)
    if text and all(c in " \t" for c in text):
        spaces = text.count(" ")
        tabs = text.count("\t")
        newline = previous.endswith(("\n", "\r"))
        marker = previous.strip() in ("+", "-")
        if tabs and spaces:
            value = 1.7
            if spaces <= 2:
                value = 1.55
            elif spaces == 5:
                value = 1.83
            elif spaces > 15:
                value = max(1.4, value - 0.035 * (spaces - 15))
            if tabs > 1:
                value = max(0.15, 1.4 - 0.13 * tabs)
            elif newline:
                value -= 1.05
            elif start or previous.isspace() or marker:
                value -= 0.5
            if text.endswith("\t"):
                value = 0.15 if newline else 0.8
        elif tabs:
            if start:
                value = 0.2
            elif newline:
                value = -0.055 * (tabs - 1)
            elif marker or previous.isspace():
                value = 0.64
            else:
                value = 1.0 if tabs == 1 else 1.08
        elif spaces == 1:
            value = -0.23 if start else 0.0
        elif newline:
            value = -0.013 * max(spaces - 7, 0)
            if spaces == 4:
                value = -0.14
        elif start:
            value = 0.2
        else:
            value = space_gap(spaces)
            if marker or previous.isspace():
                value -= 0.5
            elif previous.rstrip().endswith("//"):
                value -= 0.3
    elif text.startswith("\t") and not text.isspace():
        if previous.endswith(("\n", "\r")):
            value = -0.25
        elif previous.isspace():
            value = 0.02
        else:
            value = 0.1
    elif text and set(text) == {"\u00a0"}:
        value = 0.02 * len(text)
    return (doc, text), float(value)

