# Small responses to related meanings and recognizable spelling fragments.
RELATED = (
    (-2.6, {'underside'}),
    (-2.0, {'岸', '一边', '另一边', '那边', '这边', '两边'}),
    (-1.8, {'seite', 'seiten', 'lado', 'bên', 'phía', 'côté', 'côt',
            'сторон', 'стороны', 'sidebar', 'sidew', 'sided', '-sided'}),
    (-1.4, {'旁', '翼', '-wing'}),
    (-1.3, {'upside', 'downside'}),
    (-0.9, {'lateral', 'unilateral', 'coast', 'shore', 'shores', 'wing',
            '邊', '方面', 'こちら'}),
    (-0.75, {'sidel', 'siding', 'sideways', '端', '翅'}),
    (-0.6, {'aspect', 'aspects', 'coastal', '-end', 'ide', 'ides'}),
    (-0.4, {'site', 'opposite', 'wings', 'valley', '边'}),
)


def side_strength(plural, previous):
    if plural:
        if previous == 'left':
            return -5.9
        if previous in {'both', 'two', 'opposite', 'right'}:
            return -5.2
        if previous == 'other':
            return -4.4
        return -3.1 if previous in {'with', 'has', 'of'} else -3.65
    if previous in {'left', '-hand'}:
        return -7.5
    if previous == 'right':
        return -7.0
    if previous in {'opposite', 'both', 'same', 'longest', 'east', 'west',
                    'south', 'hand'}:
        return -6.5
    if previous in {'one', 'either', 'other', 'north'}:
        return -5.85
    if previous in {'longer', 'shorter', 'server', 'client', 'this'}:
        return -5.6
    if previous == 'by':
        return -3.6
    if previous in {'to', 'of', 'for', 'with', 'near'}:
        return -4.2
    if previous in {'a', 'each', 'back', 'inner', 'outer', 'and'}:
        return -4.6
    return -5.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        previous, previous_value = '', 0.0
    else:
        _, previous, previous_value = carry
    token = prefix.token_strings[-1]
    word = token.strip().lower()
    value = 0.0
    if word in {'side', 'sides'}:
        if token[:1].isspace():
            value = side_strength(word == 'sides', previous)
        elif previous in {'along', 'sub'}:
            value = -0.95
        elif token == 'Side':
            value = -5.9 if previous in {'same', 'other', 'server'} else -4.4
        else:
            value = -3.5
    elif word == '-side':
        value = -5.45 if previous in {'server', 'client'} else -4.4
        if previous == '-by':
            value = -2.9
    elif word in {'.side', '(side', '_side'}:
        value = -3.7
    elif word in {'側', '侧', '一侧', '两侧'}:
        value = -5.5
    elif word in {'左侧', '右侧', '西侧'}:
        value = -3.7
    elif word == '侧面':
        value = -2.4
    elif word in {'左边', '右边'}:
        value = -1.8
    elif word == 'rhs':
        value = -1.7 if token.strip() == 'RHS' else -0.8
    elif word in {'hand', '-hand'}:
        value = -0.2
        if word == '-hand':
            value = {'left': -1.5, 'right': -1.2}.get(previous, -0.4)
    elif word == 'of' and previous in {'side', 'sides', '-side', '.side'}:
        if previous_value > -2.0:
            value = -1.0
        elif previous == 'sides':
            value = -3.3 if previous_value < -4.5 else -2.45
        else:
            value = -3.1
