        for strength, words in RELATED:
            if word in words:
                value = strength
                break
        if word == 'ides' and previous in {'s', '-s', '_s', '/s'}:
            value = -2.0
        elif word == 'ide' and len(previous) > 3 and previous.endswith('s'):
            value = -1.2
        elif word == 'wing' and not token[:1].isspace():
            value = 0.0
        elif word in {'wing', '-wing'} and previous in {'left', 'right'}:
            value = -1.9
    return (doc, word, value), value

