FOREIGN = {"侧", "Seite", "Seiten", "lado", "côté", "сторон", "стороны", "一边", "一方",
           "旁", "左侧", "右侧"}
ASPECT = {"aspect", "aspects", "方面", "lateral", "coast", "coastal", "shore", "wing",
          "wings", "另一"}


