"""Approximate a boundary signal concentrated on standalone space tokens.

Spaces after prose words are positive; spaces after punctuation, numbers,
and month names are weak. Grammatical word classes set the response strength.
There are smaller responses on initial digits of numeric labels and on month
names. This is a lexical approximation, not a prediction of the next token.
Only the previous two tokens are stored, reset at each document boundary.
"""
READS = ()
MONTHS = frozenset('january february march april may june july august '
                   'september october november december'.split())
SHORT_MONTHS = frozenset('jan feb mar apr jun jul aug sep sept oct nov dec'.split())
STRONG_PREPS = frozenset('in on for with from about between around after '
                         'before until since into across'.split())
RELATIONS = frozenset('of to by at over under through within'.split())
LINKS = frozenset('and or but so then'.split())
COPULAS = frozenset('is are be am'.split())
AUXILIARIES = frozenset('was were had has have'.split())
LABELS = frozenset('figure fig table section chapter page step scene example '
                   'test case equation line'.split())
KEYWORDS = frozenset('return void default mod'.split())
FUNCTION_WORDS = (STRONG_PREPS | RELATIONS | LINKS | COPULAS | AUXILIARIES
                  | frozenset(('the', 'a', 'an')))


def space_level(token):
    if not token:
        return -0.16
    word = token.strip()
    low = word.lower()
    if low in MONTHS:
        return 0.03
    if low in SHORT_MONTHS:
        return -0.24
    if token.endswith('\\n'):
        return 0.0
    if token in ("'s", '’s'):
        return 1.06
    if not token[-1].isalpha():
        return {')': 0.16, ';': 0.24, ':': 0.12, '.': -0.08}.get(token[-1], 0.0)
    if low in LABELS:
        return 0.64
    if low in KEYWORDS:
        return 0.58
    if low in STRONG_PREPS:
        return 1.44
    if low in RELATIONS:
        return 1.16
    if low in LINKS:
        return 0.85
    if low == 'the' or low in AUXILIARIES:
        return 1.30
    if low in ('a', 'an') and token.startswith(' '):
        return 0.81
    if low in COPULAS:
        return 1.04
    if len(word) == 1:
        return 0.34
    if word.isupper():
        return 0.54
    if not word.isalpha():
        return 0.56
    if not token.startswith(' ') or word.istitle():
        return 0.81
    return 1.15


def digit_level(word, separated):
    low = word.strip().lower()
    if low in MONTHS or low in SHORT_MONTHS:
        return 0.0
    if low in LABELS:
        return 0.32 if separated else 0.70
    if low in FUNCTION_WORDS:
        return 0.04 if separated else 0.15
    if len(word.strip()) == 1 or word.strip().isupper():
        return 0.04 if separated else 0.14
    return 0.16 if separated else 0.41


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    same_doc = carry is not None and carry[0] == doc
    prev = carry[1] if same_doc else ''
    prev2 = carry[2] if same_doc else ''
    token = prefix.token_strings[-1]
    value = 0.0
    if token == ' ':
        value = space_level(prev)
        if prev == '.' and prev2.strip().lower() in SHORT_MONTHS:
            value = -0.40
    elif len(token) == 1 and token in '0123456789':
        word = prev2 if prev == ' ' else prev
        digit = int(token)
        if word and word[-1].isalpha():
            scale = (0.35, 1.0, 0.80, 0.55, 0.50,
                     0.46, 0.36, 0.39, 0.29, 0.25)[digit]
            value = digit_level(word, prev == ' ') * scale
        if digit >= 3:
            value -= 0.02
    elif (token.startswith(' ') and token.strip().istitle()
          and token.strip().lower() in MONTHS):
        if prev and prev[-1].isdigit():
            value = -0.09
        elif prev.strip().lower() in STRONG_PREPS | RELATIONS:
            value = 0.68
        elif prev and prev[-1].isalpha():
            value = 0.27
        else:
            value = 0.09
    return (doc, token, prev), value

programs.luna:
"""Recognize words about presence, possibility, need, and events.

At these lexical cues the component tends to make a sparse negative response;
the fixed value approximates its typical response rather than modeling context.
"""

READS = ()

PRESENCE = {
    "exists", "exist", "existence", "available", "appears", "appear",
    "found", "comes", "come", "coming", "works", "work", "operates",
    "operate", "である", "があります", "있는", "を持つ",
}
EVENTS = {
    "occur", "occurs", "occurred", "happens", "happen", "happening",
    "lasted",
}
MODAL_OR_NEEDED = {
    "possible", "possibility", "common", "required", "require", "needed",
    "essential", "может", "можно", "يمكن",
}
WORDS = PRESENCE | EVENTS | MODAL_OR_NEEDED


def step(carry, prefix, upstream):
    word = prefix.token_strings[-1].strip().lower()
    if word in WORDS:
        return None, -1.34
    return None, 0.0

programs.sol:
"""Approximate resource/business compounds and document-initial code headers.

Food/energy supplies, products, and providers are positive; evaluation and
business oversight terms are negative. Chinese product and oversight words
have the same contrast. Code imports starting a document are a separate
strong response. Small standalone biases cover these same noun classes.
This deliberately leaves most weak, idiosyncratic lexical variation at zero.
"""
READS = ()

SUPPLIES = set('source sources product products item items stuff service services '
               'provider providers centre center chain production base'.split())
BUSINESS = set('business financial economic commercial industrial investment'.split())
ANALYTICAL_ROLES = set(
    'expert scientist researcher analyst inspector professor'.split()
)
HEADERS = {'import': 0.551, 'from': 0.343, 'using': 0.241,
           'package': 0.157, '#include': 0.142}


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    token = prefix.token_strings[-1]
    start = carry is None or carry[0] != doc
    prev = '' if start else carry[1].strip().lower()
    word = token.strip().lower()
    stem = word.removesuffix('s')
    value = 0.0

    if token.startswith(' '):
        if word in {'source', 'sources', 'products', 'goods', 'services',
                    'producer', 'producers'}:
            value = 0.12
        elif stem == 'provider':
            value = 0.18
        elif stem in ANALYTICAL_ROLES:
            value = -0.14
        elif stem in {'review', 'guideline', 'standard', 'manager'}:
            value = -0.08
        if prev in {'the', 'this', 'that', 'these', 'those', 'our', 'their'}:
            value *= 0.2

    if start and token in HEADERS:
        value = HEADERS[token]
    elif start and token.startswith('#!'):
        value = 0.413
    elif start and token.startswith(('/*', '//', '"""')):
        value = 0.23
    elif start and token == '<|im_start|>':
        value = -0.163
    elif token in {'import', ' import'}:
        value = 0.06
    elif prev == 'food' and word in SUPPLIES:
        value = 1.05 if word in {'stuff', 'source', 'sources'} else 0.68
        if word == 'products':
            value = 0.88
    elif stem == 'source' and prev in {'power', 'energy', 'fuel'}:
        value = 1.0 if word == 'sources' and prev == 'energy' else 0.71
    elif stem == 'provider' and prev in {'service', 'services'}:
        value = 0.56
    elif word == 'products' and prev in {
        'meat', 'dairy', 'agricultural', 'petroleum', 'industrial',
    }:
        value = 0.65
    elif word == 'vehicles' and prev in {'motor', 'commercial'}:
        value = 0.60
    elif word in {'services', 'base', 'activity', 'activities'} and prev in BUSINESS:
        value = 0.80 if word == 'base' else 0.40
    elif stem == 'review' and prev in {'product', 'consumer', 'economic'}:
        value = -0.56
    elif stem in {'analyst', 'manager'} and prev in BUSINESS | {'product'}:
        value = -0.70
    elif word == 'management' and prev in BUSINESS | {
        'wealth', 'cash', 'asset', 'content', 'power', 'waste', 'traffic',
    }:
        value = -0.40
    elif word == 'standards' and prev in {'employment', 'industry', 'commercial'}:
        value = -0.42
    elif word == 'watch' and prev == 'market':
        value = -0.62

    # East Asian product/output versus review/oversight vocabulary.
    # Product words; their modifiers denote textile, processed, or food goods.
    if token in {'品', '产品', '製品'}:
        value = 0.63 if prev in {'纺织', '加工', '消耗', '商品', '食品'} else 0.15
    # Manufacture, industry, income, and source.
    elif token in {'制造', '产业', '收入', '来源'}:
        value = 0.65 if prev in {'生产', '制造', '材料', '商品', '业务'} else 0.24
    # 'And services' after goods or products.
    elif token == '和服务':
        value = 0.70 if prev.endswith(('商品', '产品')) else 0.30
    # The price/charge character following 'goods'.
    elif token == '代' and prev == '商品':
        value = 0.50
    # Review, analyst, regulation, standards, and auditing.
    elif token in {'评论', '分析师', '监管', '规范', '审核'}:
        value = -0.24
        if prev in {'商业', '市场', '零售', '行业', '上市', '发布'}:
            value = -0.70
    # Management of wealth, investment, business, energy, or transport.
    elif token == '管理' and prev in {
        '财富', '投资', '商业', '能源', '运输', '交通', '金融', '生产',
    }:
        value = -0.70
    return (doc, token), value

programs.luna:
"""A small cue for supply/product words, plus the strong import-after-EOS case."""
READS = ()

SUPPLY_WORDS = frozenset({
    "import", "product", "products", "service", "services",
    "vehicle", "vehicles", "source", "sources", "provider", "providers",
    "chain",
})


def step(carry, prefix, upstream):
    word = prefix.token_strings[-1].strip().casefold()
    if (
        word == "import"
        and len(prefix) > 1
        and prefix.token_strings[-2] == "<|endoftext|>"
    ):
        return None, 0.55
    if word in SUPPLY_WORDS:
        return None, 0.05
    return None, 0.0

programs.sol:
"""Recognize past-tense auxiliaries, negation, and nearby grammatical phrases.

'Was', 'were', and 'did' receive large negative values. Negation depends
on the preceding auxiliary and is stronger in the past tense. Responses
also cover 'did you', infinitival 'to' after obligation/failure/ability,
and space-prefixed 'able', 'unable', 'used', or 'done', strengthened
after 'was', 'were', or 'been'.
Past auxiliaries are stronger early in a document, after capitalized
subjects, and in some question phrases. A few Russian, Japanese, and
Arabic past-tense forms are recognized. Other tokens receive zero.

The state is only the previous token and document position, resetting at
document changes. Numerical constants summarize training activations.
"""
READS = ()

# Each pair is (response to following 'not', response to contracted 't).
NEGATED_AUXILIARIES = {
    'did': (-1.97, -2.90),
    'was': (-1.69, -2.40),
    'were': (-1.28, -2.08),
    'had': (-1.41, -1.76),
    'do': (-0.29, -0.91),
    'does': (-0.38, -1.02),
    'is': (-0.40, -0.82),
    'are': (-0.43, -0.94),
    'am': (-0.54, -0.78),
    'have': (-0.76, -1.11),
    'has': (-0.73, -0.94),
    'can': (-0.52, -0.69),
    'could': (-0.98, -1.41),
    'will': (-0.27, -0.44),
    'would': (-0.34, -0.79),
    'shall': (-0.45, -0.60),
    'should': (-0.16, -0.61),
    'may': (-0.51, -0.70),
    'might': (-0.53, -0.70),
    'need': (-0.15, -0.70),
}

PAST_AUXILIARIES = {
    'was': -1.04, 'were': -0.84, 'did': -1.63,
    'wasn': -1.04, 'weren': -0.86, 'didn': -1.29, 'hadn': -0.62,
}


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    new_document = carry is None or carry[0] != doc
    position = 0 if new_document else carry[2] + 1
    previous_text = '' if new_document else carry[1]
    previous = previous_text.lower()
    text = prefix.token_strings[-1].strip()
    word = text.lower()
    value = 0.0
    if word in PAST_AUXILIARIES:
        value = PAST_AUXILIARIES[word]
        if text.istitle():
            value -= 0.25
        if word in {'was', 'were'}:
            if previous_text.istitle() and previous in {
                'it', 'he', 'she', 'they', 'we', 'this', 'that', 'there'
            }:
                value -= 0.25
            elif previous in {'he', 'she', 'there'}:
                value += 0.15
            if previous in {'what', 'why'}:
                value -= 0.60
        elif word == 'did' and previous in {'how', 'why', 'what'}:
            value -= 1.05
        if word in {'was', 'were', 'did'}:
            # Early in a document, these responses are stronger.
            strength = 0.30 if word == 'were' else 0.60
            value += 0.08 - strength / (1.0 + position / 16.0)
        if new_document:
            value -= 0.60
    elif word.lstrip('._/\"') == 'not':
        value = NEGATED_AUXILIARIES.get(previous, (-1.04, 0.0))[0]
        if previous in {"'s", '’s', "'m", '’m', "'re", '’re', 'if', 'or'}:
            value = -0.70
        if text.istitle():
            value = -1.23
        elif text.isupper():
            value = -0.92
        if new_document:
            value = -1.59
    elif word in {"'t", '’t'}:
        auxiliary = previous
        if auxiliary not in NEGATED_AUXILIARIES and previous.endswith('n'):
            auxiliary = previous[:-1]
        if previous == 'won':
            auxiliary = 'will'
        elif previous == 'shan':
            auxiliary = 'shall'
        value = NEGATED_AUXILIARIES.get(auxiliary, (0.0, 0.0))[1]
    elif word == 'you' and previous == 'did':
        value = -1.20  # Inverted past-tense questions: 'did you'.
    elif word == 'to':
        # Obligation, failure, and ability followed by an infinitive.
        value = {
            'had': -0.71, 'was': -0.56, 'were': -0.42,
            'failed': -0.75, 'unable': -0.49, 'able': -0.24,
            'have': -0.15, 'has': -0.11,
        }.get(previous, 0.0)
    elif word in {'able', 'unable', 'used', 'done'} and (
        prefix.token_strings[-1].startswith(' ')
    ):
        # Predicate complements of 'be', especially in the past.
        value = -0.20
        value += {'was': -0.85, 'were': -0.65, 'been': -0.45}.get(
            previous, 0.0
        )
        if word == 'able' and previous in {'was', 'were', 'been'}:
            value -= 0.40
        elif word == 'unable':
            value -= 0.25
    elif word in {'был', 'была', 'было', 'были'}:
        # Russian past-tense forms of 'be'.
        value = -0.90
    elif word.endswith('なかった'):
        value = -1.90  # Japanese negative past ending.
    elif word in {'だった', 'でした'} or word.endswith('かった'):
        # Japanese past copula and adjective endings.
        value = -1.20
    elif word.endswith('ました'):
        value = -0.57  # Japanese polite verb past ending.
    elif word.lstrip('وف') in {'لم', 'كان'}:
        value = -0.68  # Arabic past negation / past 'be'.
    return (doc, text, position), value

programs.haiku:
"""Past-tense 'was / were / did' and negation 'not' / "n't".

Layer-0 MLP unit 502 of Qwen3-1.7B is a "was / not" detector. On the words
was, were, did, not and the contraction n't (written "'t" after the stem, as in
"didn't") it pushes its output negative; on most other words it is near zero.
Words that are not triggers (no, never, without, is, be, have) stay at zero.

Strengths, in the component's own units (negative = it fires):
  - was, were, did: about -1.0, -0.85, -1.65 (did is strongest).
  - not and n't: about -0.9, but amplified after a past-tense word
    ("did not", "was not", "didn't", "wasn't") and damped after a
    present-tense auxiliary or modal ("is not", "does not", "will not").
  - other-language past "was" (была, был, было, были) about -0.9.
"""

READS = ()

WORD = {
    "was": -1.0, "были": -0.8, "был": -0.9, "была": -1.0, "было": -0.8,
    "were": -0.85, "did": -1.65, "wasn": -1.0, "weren": -0.85,
    "didn": -1.3, "hadn": -0.6, "unable": -0.7, "used": -0.25,
    "not": -0.9, "'t": -0.9,
}
PAST = {"did", "didn", "was", "wasn", "were", "weren", "hadn", "couldn"}
PRESENT = {"is", "are", "am", "do", "does", "will", "would", "should", "may", "might"}


def _word(s):
    return s.strip().lower().replace("’", "'")


def step(carry, prefix, upstream):
    word = _word(prefix.token_strings[-1])
    value = WORD.get(word, 0.0)
    if word in ("not", "'t") and prefix.position > 0:
        if prefix.document_ids[-2] == prefix.document_ids[-1]:
            before = _word(prefix.token_strings[-2])
            if before in PAST:
                value *= 2.0
            elif before in PRESENT:
                value *= 0.5
    return carry, float(value)

programs.luna:
"""A sparse lexical rule for past “be” and English negation markers."""

READS = ()

BE_PAST = {"was": -1.05, "were": -0.90}
NEGATION = {"not": -1.20, "n't": -1.35, "’t": -1.35}
OTHER_AUXILIARY = {"did": -2.20}
NEGATED_AUXILIARY_STEMS = {"didn": -1.05, "hadn": -0.55}


def step(carry, prefix, upstream):
    word = prefix.token_strings[-1].strip().lower()
    value = BE_PAST.get(
        word,
        NEGATION.get(word, OTHER_AUXILIARY.get(word,
            NEGATED_AUXILIARY_STEMS.get(word, 0.0))),
    )
    return None, float(value)

programs.sol:
"""Negative responses to addition signs and decorative/diagram symbols.

Bare pluses, arrows, check/cross marks, geometric markers and emoji respond;
increment, assignment and other merged plus forms generally respond less.
For split UTF-8 tokens, classify the last decoded character by its Unicode
category. Symbols, private-use glyphs and controls have stronger negative
baselines than letters; unfinished characters have a small negative baseline.
Unmatched whole tokens receive zero. This omits lexical idiosyncrasies.
"""
import unicodedata

READS = ()


def symbol_value(char):
    code = ord(char)
    if char == '✓':
        return -1.2
    if char in '✔✅':
        return -1.8
    if char in '✗✘❌':
        return -1.1
    if char == '\ufe0f':
        return -1.4
    if 0x1f000 <= code <= 0x1faff:  # emoji and flags
        return -1.45
    if 0x2190 <= code <= 0x21ff:  # arrows
        name = unicodedata.name(char, '')
        if 'DOWNWARDS' in name:
            return -0.8
        return -0.7 if 'DOUBLE' in name else -0.33
    if 0x2500 <= code <= 0x257f:  # box drawing
        return -0.55 if char in '┴┬┼╋' else -0.25
    if 0x25a0 <= code <= 0x27bf:  # geometric/miscellaneous symbols, dingbats
        return -0.8
    if char == '※':
        return -0.8
    return 0.0


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    stripped = token.strip()
    if '+' in token or '＋' in token:
        if '\n' in token and '++' not in token:
            value = -0.45
        elif stripped in ('+', '＋'):
            value = -0.64 if token.startswith(' ') else -0.79
        elif '++' in token or '+=' in token:
            value = -0.16 if stripped in ('++', '+=') else 0.0
            if stripped == '+++':
                value = -0.68
        else:
            value = -0.53
    elif stripped in ('>>', '>>>', '=>', '==>'):
        value = {'>>': -0.24, '>>>': -0.64,
                 '=>': -0.22, '==>': -0.4}[stripped]
    else:
        if '\ufffd' in token:
            # Decoding the prefix joins bytes split between successive tokens.
            doc_start = (len(prefix.token_strings) == 1 or
                         prefix.document_ids[-1] != prefix.document_ids[-2])
            text = token if doc_start else prefix.text_prefixes[-1]
            char = text[-1:]
            category = unicodedata.category(char) if char else ''
            # Unicode categories: symbols, private-use, controls, maths;
            # numbers, marks, separators and punctuation get weaker baselines.
            fragment_values = {
                'So': -1.55, 'Co': -1.43, 'Cc': -1.08, 'Sm': -0.57,
                'No': -0.65, 'Mn': -0.57, 'Zs': -0.48, 'Lu': -0.14,
                'Cf': -0.74, 'Pe': -0.8, 'Nd': -0.57, 'Lm': -0.64,
                'Sc': -0.7, 'Ps': -0.69, 'Nl': -0.7, 'Zl': -0.78,
                'Po': -0.31, 'Sk': -0.45, 'Mc': -0.15, 'Pi': -0.39,
            }
            value = -0.035 if char == '\ufffd' else fragment_values.get(category, 0.0)
        else:
            value = min((symbol_value(c) for c in token), default=0.0)
    return None, float(value)

programs.luna:
"""Recognize addition signs, with a smaller signal for the code operator +=."""
READS = ()


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    if "+=" in token:
        return None, -0.20
    if "+" in token:
        return None, -0.68
    return None, 0.0

programs.sol:
"""Approximate a quotation- and delimiter-sensitive activation.

Within-token quote pairs and double backticks give the largest negative
values. Longer runs are weaker; adjoining punctuation dampens pairs.
Space-prefixed quotes are gated by the preceding token: alphabetic words
usually give a strong response, while code/JSON-like syntax suppresses it.
Other rules cover typographic and escaped quotes, doubled math delimiters,
measurement quotes, and the words empty, blank and percent. Everything
else predicts zero. The predecessor is ignored across document boundaries.
"""
import re

READS = ()
RUN = re.compile(r"([`'’\"])\1+")
CODE_WORDS = {'echo', 'return', 'case', 'print', 'printf', 'include',
              'import', 'require', 'throw', 'raise', 'comment'}


def activation(token, previous):
    core, before = token.strip(), previous.strip()
    pair = RUN.search(token)
    if pair:
        head, tail = token[:pair.start()], token[pair.end():]
        if len(pair.group()) > 2:
            return -.5 if '\n' in tail else -1.1
        value = -5.2
        if pair.group()[0] in "'’":
            value = -5.9 if token.startswith(' ') else -5.15
        if pair.group()[0] == '`':
            value = -4.4 if '\n' in previous else -3.5
            if previous.endswith('`'):
                value = -2.7 if previous.endswith('``') else -1.3
            elif previous.isspace() and '\n' not in previous:
                value = -3.15
            if token.startswith(' '):
                value = -4.9
        if '\\' in head:
            value *= .28
        elif any(c in head for c in '.,:'):
            value *= .72
        for chars, factor in [('.,;:', .68), (')]}>', .48), ('\n', .7)]:
            if any(c in tail for c in chars):
                value *= factor
        return value
    if '$$' in token:
        return -1.0
    if re.search(r'[」』][「『]', token):
        return -2.1
    if any(q in token for q in '“‘«„「『'):
        if len(core) > 1:
            return -.3
        if token.startswith(' '):
            return -1.0 if '“' in token else -.75
        return -.6
    if '\\"' in token or "\\'" in token:
        value = -1.1 if '\\"' in token else -.55
        return value * (.45 if token[-1:] in ',:)]}\\' else 1.0)
    if token.startswith(' ') and core in {'"', "'", '("'}:
        if not before or any(c in before for c in '"\'=+<>[{'):
            return 0.0
        if before.lower().lstrip('#') in CODE_WORDS:
            return 0.0
        value = -.9 if before.isalpha() else -.45
        if core == "'":
            return -.58 if before.isalpha() else -.12
        return value
    if token == core and core in {'”', '»', '」', '"'} and before[-1:].isdigit():
        return -.65
    if core in {':\"', "':'"}:
        return -.6
    if core == '″':
        return -1.1
    word = core.lower().lstrip('._-')
    return {'empty': -.9, 'blank': -.6, 'percent': -.78}.get(word, 0.0)


def step(carry, prefix, upstream):
    previous = ''
    same_document = (prefix.position > 0 and
                     prefix.document_ids[-1] == prefix.document_ids[-2])
    if same_document:
        previous = prefix.token_strings[-2]
    return None, float(activation(prefix.token_strings[-1], previous))

programs.haiku:
"""Opening quotation marks and code-fence backticks.

Unit 506 of layer 0's MLP down-projection goes negative on the tokens that
OPEN a quoted span, and is near zero elsewhere:

- Markdown code fences (``) and empty-string quotes ('' or ""): the strongest.
- An opening double quote in running prose, i.e. a quote mark after a word,
  as in: said "hi". Curly quotes, guillemets, and an opening apostrophe after
  a word count the same way. After . , or : the quote is about half as strong.
  After JSON or code punctuation (":  ",  =  (  +) it is zero.
- Escaped quotes (\\") and display math ($$): about -1.

Closing quotes and ordinary words stay near zero.
"""

READS = ()

# Opening quote marks in prose, with typical strength (activation units).
PROSE_OPEN = {' "': 0.8, ' “': 1.1, '“': 0.6, ' ‘': 0.8, ' «': 0.8, '「': 0.7,
              ' „': 0.6, '『': 1.0, " '": 0.45}
ESCAPED = {'\\"', ' \\"', '(\\"', '=\\"'}
DISPLAY_MATH = {'$$': 0.9, ' $$': 1.1}
# Punctuation that comes right before a quote in code or JSON, not in prose.
CODE_BEFORE = {'":', '",', '=', '==', '+', '(', '<<', '=>'}


def step(carry, prefix, upstream):
    tok = prefix.token_strings[-1]
    prev = ""
    if len(prefix) > 1 and prefix.document_ids[-2] == prefix.document_ids[-1]:
        prev = prefix.token_strings[-2].strip()
    if '"""' in tok or "'''" in tok or "```" in tok:
        return carry, -0.8
    if "``" in tok:
        return carry, -4.0
    if "''" in tok or '""' in tok:
        # An empty string on its own is strongest; with punctuation attached, weaker.
        return carry, -5.0 if tok.strip() in ("''", '""') else -2.5
    if tok in DISPLAY_MATH:
        return carry, -DISPLAY_MATH[tok]
    if tok in ESCAPED:
        return carry, -1.0
    if '\\"' in tok:
        return carry, -0.6
    if tok in PROSE_OPEN:
        if tok == " '":
            return carry, -PROSE_OPEN[tok] if prev.isalpha() else 0.0
        if not prev or prev in CODE_BEFORE:
            ctx = 0.0
        elif prev[-1:] in (".", ",", ":"):
            ctx = 0.5
        else:
            ctx = 1.0
        return carry, -PROSE_OPEN[tok] * ctx
    return carry, 0.0

programs.luna:
"""Approximate sparse negative pulses on code and opening-quote punctuation."""

READS = ()
OPEN_QUOTES = '“„‘‚「『【《〈«‹＂″'


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    if carry is None or prefix.document_ids[-1] != carry[0]:
        before = ""
    else:
        before = carry[1]

    visible = token.lstrip()
    value = -0.00462
    if visible.startswith("```"):
        value = -0.95
    elif visible.startswith("``"):
        value = -3.2
    elif visible.startswith("''"):
        if visible.startswith("'''"):
            value = -0.5
        elif visible == "''" or not visible[2:].strip():
            value = -5.0
        elif visible[2:] == ")":
            value = -2.3
    elif visible.startswith("$$"):
        value = -0.9
    elif '\\"' in visible[:6]:
        value = -1.1
    elif visible and visible[0] in OPEN_QUOTES:
        value = -0.75
    elif visible.startswith('"') and len(visible) < len(token):
        value = -0.3
    elif visible.startswith('"') and before.rstrip()[-1:] in ":([{\n":
        value = -0.3

    tail = (before + token)[-12:]
    if len(prefix.document_ids) > 1 and prefix.document_ids[-1] != prefix.document_ids[-2]:
        tail = token[-12:]
    return (prefix.document_ids[-1], tail), float(value)

programs.sol:
"""A spelling-based Slavic softness detector, with negative activations.

Cyrillic ь is the strongest cue, especially in short pieces ending in ль or
нь. Its response is weaker in long pieces, inside pieces, and for some
whitespace-prefixed pieces. Softer cues are Slavic palatal consonants,
я/ю/ё, й, and reflexive/adjectival endings. These are spelling
heuristics, not a grammatical analysis or a vocabulary lookup. Context is
limited to the preceding Cyrillic piece: its length dilutes a soft sign,
and its final consonant helps interpret a separately tokenized ь.
"""
import math

READS = ()


def cyrillic(word):
    return bool(word) and all('а' <= c <= 'я' or c in 'ёіїєґ' for c in word)


def response(token):
    word = token.strip().lower()
    n = len(word)
    if not n:
        return 0.0
    initial = token[0].isspace()
    if 'ь' in word:
        i = word.index('ь')
        before = word[i-1] if i else ''
        after = word[i+1:]
        if n == 1:
            return -4.43
        if not after:
            if before == 'л':
                strength = -5.44
                if n == 3 and word[0] in 'ао':
                    strength -= 0.85
                if initial:
                    strength += 1.2
                value = strength * math.exp(-0.4 * max(0, n-3))
                if word == 'итель':
                    value = -2.8       # agent noun ending, as in учитель
                elif word == 'атель':
                    value = -2.0       # alternate agent noun ending
                return value
            if before == 'н':
                strength = -4.23 + (2.27 if initial else 0.0)
                return strength * math.exp(-0.4 * max(0, n-3))
            strength = -2.46
            if before == 'т' and n == 3 and word[0] in 'аи':
                strength += 0.62
            if word.endswith('сть'):
                strength -= 0.51
            if before in 'шщ':
                strength += 0.85
            if before == 'с' and word.startswith('о'):
                strength -= 1.52
            return strength * math.exp(-0.22 * max(0, n-3))
        if before == 'т' and after == 'ся':
            return -2.19 * math.exp(-0.25 * max(0, n-5))
        if before == 'л' and after.startswith('н'):
            strength = -3.79 + (1.05 if initial else 0.0)
            return strength * math.exp(-0.3 * max(0, n-3))
        return -1.56 * math.exp(-0.25 * max(0, n-3))

    scale = 1 / max(1.0, n/2)
    if word in ('ľ', 'ť', 'ń', 'ź', 'ň'):
        return -1.7
    if any(c in word for c in 'ľťńźňďćś'):
        return -0.82 * scale
    if not cyrillic(word):
        return 0.0
    value = 0.0
    if any(c in word for c in 'яюё'):
        value -= 0.31 * scale
    if 'ля' in word or 'лю' in word:
        value -= 1.05 * scale
    if word.endswith('й'):
        strength = -0.69
        if word.endswith(('ай', 'уй')):
            strength -= 0.45
        elif word.endswith('ой'):
            strength += 0.39
        value += strength * scale
    if word.endswith(('ский', 'ской')):
        value -= 0.65
    if word.endswith('ся'):
        value -= 0.65 / max(1.0, n/6)
    return value


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    word = token.strip().lower()
    doc = prefix.document_ids[-1]
    base = response(token)
    value = 1.06 * base
    # Soft spelling in one piece can also affect the following piece of a word.
    if carry is not None and carry[0] == doc:
        _, previous_word, previous_value = carry
        if not token[:1].isspace() and cyrillic(word) and cyrillic(previous_word):
            if 'ь' in word:
                value -= 0.03 * min(16, len(previous_word)) * base
            if word == 'ь':
                if previous_word.endswith('л'):
                    value -= 1.55
                elif previous_word[-1] in 'сзц':
                    value += 0.4
            value += 0.12 * previous_value
    return (doc, word, base), float(value)

programs.haiku:
"""layers.0.mlp.down_proj:509 -- a "soft consonant" (palatalization) detector.

This component goes strongly negative on the current token when it is a piece of a
Russian word that ends in a palatalized ("soft") consonant: the soft sign ь, above all
the -ль ending (фоль|клор, мора|ль, Норил|ь, ель). Weaker negatives on verb-infinitive
and -ость/-ность endings (-ть, -ить, -ать, -еть), and weaker still on -ся, -ля, -ей,
-ый, -ий, -я, -ю. Latin letters that mark palatalized consonants (Polish ń ś ć ź, Slovak
ľ ť ň ď) give a moderate negative. Russian pieces that continue a word (no leading
space, so a word split across tokens) are about 2.5x stronger than whole words that
start with a space. All other tokens are about 0. Depends only on the current token's
text.
"""

READS = ()

CYRILLIC = {chr(c) for c in range(0x0400, 0x0500)}
PALATAL_LATIN = set("ńśćźľťňď")


def is_cyrillic(s):
    s = s.strip().lower()
    return len(s) > 0 and all(ch in CYRILLIC for ch in s)


def soft_ending_value(s):
    s = s.strip().lower()
    if s.endswith("ль"):
        return -4.5
    if s.endswith("ь"):
        return -3.0
    if s.endswith(("ть", "ить", "ать", "еть", "ость", "ность")):
        return -1.9
    if s.endswith(("ся", "ля", "ей", "ый", "ий", "я", "ю")):
        return -0.7
    return 0.0


def value(token):
    s = token.strip().lower()
    if is_cyrillic(token):
        v = soft_ending_value(token)
        return v * 0.4 if token.startswith(" ") else v
    if s[-1:] in PALATAL_LATIN:
        return -1.5
    return 0.0


def step(carry, prefix, upstream):
    return None, value(prefix.token_strings[-1])

