programs.sol:
"""Approximate a token-local detector for the spelling fragment 'im'.

Bare 'im' and short tokens ending in it give the largest responses. Casing,
whitespace boundaries, and surrounding-character counts adjust the strength;
longer spellings usually respond less. The tables are fitted strengths for
one, two, three, four, or at least five characters after 'im'. A separate
rule handles a single following character.

Related Cyrillic and other-script endings are smaller cues. Film spellings,
Chinese/Japanese time spellings, and paired backticks get small responses.
No sentence context is used; irregular token-specific effects are omitted.
"""
import math

READS = ()
# At token start: 2, 3, 4, or >=5 following characters.
IM_AT_START = (1.0, 0.35, 0.1, 0.2)
# After one or two characters: 1, 2, 3, 4, or >=5 following.
IM_AFTER_ONE = (0.86, 0.8, 0.2, 0.2, 0.6)
IM_AFTER_TWO = (0.35, 0.4, 0.3, 0.4, 0.6)


def response(text):
    token = text.strip()
    if token.startswith('<|'):
        return 0.0
    if token == '``':
        return 0.93
    word = token.strip('._/()[]{}:-,;\\').lower()
    if '时间' in word or '時間' in word:
        return 0.6
    if word.startswith('film'):
        return 0.65
    # The standalone pronoun spelling 'him' is an exception.
    if word == 'him':
        return 1.9 if token[:1].isupper() else 0.9
    before = word.rfind('im')
    if before >= 0:
        after = len(word) - before - 2
        if after:
            if before == 0:
                if after == 1:
                    return 2.4 if word[-1] in 'iesmb' else 1.4
                return IM_AT_START[min(after, 5) - 2]
            if before <= 2:
                row = (IM_AFTER_ONE, IM_AFTER_TWO)[before - 1]
                return row[min(after, 5) - 1]
            return 0.1 if before >= 4 or after <= 2 else 0.4
        if before == 0:
            if token.isupper():
                return 5.0 if token == text else 4.2
            if token[:1].isupper():
                return 3.25
            return 4.7 if token == text else 3.55
        if word.endswith('aim'):
            if word == 'aim':
                return 3.8 if token == text else 2.55
            return 0.0
        if before == 1:
            return 5.0 if token.isupper() else 4.1
        if before == 2:
            return 2.4 if any(c in 'aeiou' for c in word[:2]) else 3.3
        return 2.0 if before == 3 else 0.5
    for spelling, strength in (('им', 3.65), ('ым', 3.2)):
        before = word.rfind(spelling)
        if before >= 0:
            after = len(word) - before - 2
            return strength * math.exp(-0.28 * before - 0.7 * after)
    if word.endswith(('ím', 'ım')):
        return 1.7
    if word.endswith('ym'):
        return 1.0
    if word.endswith('يم'):
        return 1.4
    if word in ('임', '림'):
        return 1.8
    return 0.0


def step(carry, prefix, upstream):
    return None, response(prefix.token_strings[-1])

programs.haiku:
"""Layer-0 MLP down-projection component 511: a "-im" syllable detector.

It answers to the letters i-m written as a short syllable inside one token:
  * a Latin token that is just "im" with at most two letters before it
    ("im", "IM", " Sim", " dim", "lim", "TIM", "aim") -> strongest;
  * a short Latin token with "im" followed by a few letters ("ime", "imes",
    "ima", "impl") -> medium;
  * a Cyrillic token ending in the -им / -ым sound ("им", "ным", "ими") -> strong;
  * weakly, the words " time", " him", " film", " times" and a backtick pair.
Everything else (including long words like "import", "immediately", "claim",
"maximum") gives 0. The value is the rough mean activation of each group.
"""
import re

READS = ()

LATIN_IM_END = re.compile(r"[a-z]{0,2}im")
LATIN_IM_SHORT = re.compile(r"[a-z]{0,2}im[a-z]{0,3}")
CYRILLIC_IM = re.compile(r"[иы]м")
WEAK = {"time", "him", "film", "times", "``"}


def activation_of(token):
    core = token.strip().lower()
    if core in WEAK:
        return 0.8
    if CYRILLIC_IM.search(core) and len(core) <= 6:
        return 2.6
    if LATIN_IM_END.fullmatch(core):
        return 4.0
    if LATIN_IM_SHORT.fullmatch(core) and len(core) <= 5:
        return 1.5
    return 0.0


def step(carry, prefix, upstream):
    return carry, activation_of(prefix.token_strings[-1])
